import { createRoute, z } from '@hono/zod-openapi'

const DatabaseRegionOptionsSchema = z
  .object({
    regions: z
      .array(z.string())
      .exactOptional()
      .openapi({
        example: ['ams3', 'blr1'],
        readOnly: true,
        description: 'An array of strings containing the names of available regions',
      }),
  })
  .openapi({ required: [] })
  .openapi('DatabaseRegionOptions')

const DatabaseVersionOptionsSchema = z
  .object({
    versions: z
      .array(z.string())
      .exactOptional()
      .openapi({
        example: ['4.4', '5.0'],
        readOnly: true,
        description: 'An array of strings containing the names of available regions',
      }),
  })
  .openapi({ required: [] })
  .openapi('DatabaseVersionOptions')

const DatabaseLayoutOptionSchema = z
  .object({
    num_nodes: z.int().exactOptional().openapi({ example: 1 }),
    sizes: z
      .array(z.string())
      .exactOptional()
      .openapi({
        example: ['db-s-1vcpu-1gb', 'db-s-1vcpu-2gb'],
        readOnly: true,
        description: 'An array of objects containing the slugs available with various node counts',
      }),
  })
  .openapi({ required: [] })
  .openapi('DatabaseLayoutOption')

const DatabaseLayoutOptionsSchema = z
  .object({
    layouts: z
      .array(DatabaseLayoutOptionSchema)
      .exactOptional()
      .openapi({
        readOnly: true,
        description:
          "An array of objects, each indicating the node sizes (otherwise referred to as slugs) that are available with various numbers of nodes in the database cluster. Each slugs denotes the node's identifier, CPU, and RAM (in that order).",
      }),
  })
  .openapi({ required: [] })
  .openapi('DatabaseLayoutOptions')

const DatabaseVersionAvailabilitySchema = z
  .object({
    end_of_life: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        example: '2023-11-09T00:00:00Z',
        description:
          'A timestamp referring to the date when the particular version will no longer be supported. If null, the version does not have an end of life timeline.',
      }),
    end_of_availability: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        example: '2023-05-09T00:00:00Z',
        description:
          'A timestamp referring to the date when the particular version will no longer be available for creating new clusters. If null, the version does not have an end of availability timeline.',
      }),
    version: z
      .string()
      .exactOptional()
      .openapi({ example: '8', description: 'The engine version.' }),
  })
  .openapi({ required: [] })
  .openapi('DatabaseVersionAvailability')

const DatabaseVersionAvailabilitiesSchema = z
  .array(DatabaseVersionAvailabilitySchema)
  .openapi({
    description:
      'An array of objects, each indicating the version end-of-life, end-of-availability for various database engines',
  })
  .openapi('DatabaseVersionAvailabilities')

