const LogsFieldRefSchema = z
  .object({
    name: z
      .string()
      .openapi({
        description:
          "The field name. Intrinsic columns include `timestamp`, `severity_text`, `severity_number`, `body`, `trace_id`, `span_id`, and `trace_flags`. The dotted shorthands `service.name`, `resource.type`, and `resource.urn` are also supported. Arbitrary resource or log attributes can be accessed with `ResourceAttributes['key']` or `LogAttributes['key']`.",
        example: 'service.name',
      }),
    scope: z
      .enum(['FIELD_SCOPE_RESOURCE', 'FIELD_SCOPE_ATTRIBUTES'])
      .exactOptional()
      .openapi({
        description:
          'The attribute scope to resolve the field against. Omit to let the server apply its default mapping for the field name.',
        example: 'FIELD_SCOPE_RESOURCE',
      }),
  })
  .openapi({
    description: 'A reference to a logical field for filters, ordering, grouping, or facets.',
    required: ['name'],
  })
  .openapi('LogsFieldRef')

const LogsFilterValueSchema = z
  .object({
    string_value: z.string().exactOptional().openapi({ example: 'droplet-123' }),
    number_value: z.number().exactOptional().openapi({ example: 42 }),
    bool_value: z.boolean().exactOptional().openapi({ example: true }),
    string_array_value: z
      .object({
        values: z
          .array(z.string())
          .min(1)
          .openapi({ example: ['droplet-123', 'droplet-456'] }),
      })
      .exactOptional()
      .openapi({ required: ['values'] }),
    number_array_value: z
      .object({
        values: z
          .array(z.number())
          .min(1)
          .openapi({ example: [42, 84] }),
      })
      .exactOptional()
      .openapi({ required: ['values'] }),
  })
  .refine((val) => Object.keys(val).length >= 1)
  .refine((val) => Object.keys(val).length <= 1)
  .openapi({
    description:
      'A typed literal or list value for a filter condition. Exactly one kind is set per message.',
    required: [],
  })
  .openapi('LogsFilterValue')

const LogsFilterConditionSchema = z
  .object({
    field: LogsFieldRefSchema,
    operator: z
      .enum([
        'FILTER_OPERATOR_EQ',
        'FILTER_OPERATOR_NEQ',
        'FILTER_OPERATOR_IN',
        'FILTER_OPERATOR_EXISTS',
        'FILTER_OPERATOR_GTE',
        'FILTER_OPERATOR_LTE',
      ])
      .openapi({ description: 'The comparison operator.', example: 'FILTER_OPERATOR_EQ' }),
    value: LogsFilterValueSchema.exactOptional(),
  })
  .openapi({
    description: 'A single field comparison in a logs filter expression.',
    required: ['field', 'operator'],
  })
  .openapi('LogsFilterCondition')

type LogsFilterExpressionType = {
  condition?: z.infer<typeof LogsFilterConditionSchema>
  and?: { expressions: LogsFilterExpressionType[] }
  or?: { expressions: LogsFilterExpressionType[] }
  not?: LogsFilterExpressionType
  text_search?: { query: string }
}

const RegionStateSchema = z
