const ApiModelUsecaseSchema = z
  .enum([
    'MODEL_USECASE_UNKNOWN',
    'MODEL_USECASE_AGENT',
    'MODEL_USECASE_FINETUNED',
    'MODEL_USECASE_KNOWLEDGEBASE',
    'MODEL_USECASE_GUARDRAIL',
    'MODEL_USECASE_REASONING',
    'MODEL_USECASE_SERVERLESS',
    'MODEL_USECASE_EVALUATION_JUDGE',
    'MODEL_USECASE_CODING',
    'MODEL_USECASE_AUDIO',
    'MODEL_USECASE_RERANKING',
    'MODEL_USECASE_TEXT',
  ])
  .default('MODEL_USECASE_UNKNOWN')
  .openapi({
    description:
      '- MODEL_USECASE_UNKNOWN: The use case of the model is unknown\n - MODEL_USECASE_AGENT: The model maybe used in an agent\n - MODEL_USECASE_FINETUNED: The model maybe used for fine tuning\n - MODEL_USECASE_KNOWLEDGEBASE: The model maybe used for knowledge bases (embedding models)\n - MODEL_USECASE_GUARDRAIL: The model maybe used for guardrails\n - MODEL_USECASE_REASONING: The model usecase for reasoning\n - MODEL_USECASE_SERVERLESS: The model usecase for serverless inference\n - MODEL_USECASE_EVALUATION_JUDGE: The model usecase for evaluation judge\n - MODEL_USECASE_CODING: The model usecase for coding-optimized models\n - MODEL_USECASE_AUDIO: The model usecase for audio models\n - MODEL_USECASE_RERANKING: The model usecase for knowledge base reranking (cross-encoder) models\n - MODEL_USECASE_TEXT: The model usecase for text modality (non image, non audio, non embedding, non reranking) serverless chat models',
    example: 'MODEL_USECASE_UNKNOWN',
  })
  .openapi('ApiModelUsecase')

const ApiModelVersionSchema = z
  .object({
    major: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({
        type: 'integer',
        format: 'int64',
        description: 'Major version number',
        example: 123,
      }),
    minor: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({
        type: 'integer',
        format: 'int64',
        description: 'Minor version number',
        example: 123,
      }),
    patch: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({
        type: 'integer',
        format: 'int64',
        description: 'Patch version number',
        example: 123,
      }),
  })
  .openapi({ description: 'Version Information about a Model', required: [] })
  .openapi('ApiModelVersion')

