const AgentConfigSchema = z
  .object({
    id: z.uuid().openapi({ example: '019fb39c-14d9-7080-933e-b9b90e25acda' }),
    name: z.string().openapi({ example: 'support-agent' }),
    agentspec_schema_version: z
      .string()
      .openapi({
        description:
          "The manifest contract the server accepted at create time: the manifest's own apiVersion for legacy envelope parses (currently agents.digitalocean.com/v1alpha1), or agents.digitalocean.com/flat.v1 for flat-format parses.",
        example: 'agents.digitalocean.com/v1alpha1',
      }),
    manifest: AgentManifestSchema.openapi({
      description:
        'Canonical runnable environment spec JSON, immutable after create. Validated non-secret spec.env and spec.permissions remain; spec.secrets retains name/source/provider but omits ref and the write-only value; metadata.name is cleared while safe metadata such as labels remains.',
    }),
    content_hash: z
      .string()
      .regex(/^[0-9a-f]{64}$/)
      .openapi({
        description: 'Lowercase SHA-256 hex digest of the canonical sanitized manifest JSON.',
        example: '75803fef24dc731824ecd4a1853c76153c7d8503534092b94da3ca3f31a882f4',
      }),
    insights: InsightsOptInSchema.and(
      z
        .any()
        .openapi({
          description:
            'The per-signal telemetry opt-in recorded at create time. Absent when the customer expressed no choice. This echoes the create-time request only: a customer who later re-toggles a signal from the Insights settings page changes their enablement there, not here.',
        }),
    ).exactOptional(),
    created_by: z
      .string()
      .openapi({
        description: 'Authenticated user identity that created the config.',
        example: 'user-1',
      }),
    created_at: z.iso.datetime({ offset: true }).openapi({ example: '2026-08-01T12:00:00Z' }),
    updated_at: z.iso.datetime({ offset: true }).openapi({ example: '2026-08-01T12:00:00Z' }),
    credentials: z
      .array(AgentConfigCredentialSlotSchema)
      .exactOptional()
      .openapi({
        description:
          'Redacted credential slot metadata (name/source/provider). Secret values are never included.',
      }),
  })
  .openapi({
    description:
      'Immutable team-scoped Environment Config: one sanitized manifest per config. There is no update; clone to a new config to change content.',
    required: [
      'id',
      'name',
      'agentspec_schema_version',
      'manifest',
      'content_hash',
      'created_by',
      'created_at',
      'updated_at',
    ],
  })
  .openapi('AgentConfig')

const AgentConfigResponseSchema = z
