const AppEventSchema = z
  .object({
    id: z
      .string()
      .exactOptional()
      .openapi({
        title: 'The ID of the event (UUID)',
        example: 'ba32b134-569c-4c0c-ba02-8ffdb0492ece',
      }),
    type: z
      .enum(['UNKNOWN', 'DEPLOYMENT', 'AUTOSCALING'])
      .exactOptional()
      .openapi({ description: 'The type of event', example: 'DEPLOYMENT' }),
    created_at: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({ title: 'When the event was created', example: '2023-10-01T12:00:00Z' }),
    deployment_id: z
      .string()
      .exactOptional()
      .openapi({
        title: 'The deployment ID associated with this event',
        description:
          "For deployment events, this is the same as the deployment's ID. For autoscaling events, this is the deployment that was autoscaled.",
        example: 'c020763f-ddb7-4112-a0df-7f01c69fc00b',
      }),
    deployment: AppsDeploymentSchema.exactOptional(),
    autoscaling: z
      .object({
        phase: z
          .enum(['UNKNOWN', 'PENDING', 'IN_PROGRESS', 'SUCCEEDED', 'FAILED', 'CANCELED'])
          .exactOptional()
          .openapi({
            description: 'The current phase of the autoscaling event',
            example: 'SUCCEEDED',
          }),
        components: z
          .record(
            z.string(),
            z
              .object({
                from: z
                  .preprocess(
                    (val) =>
                      typeof val === 'number' && Number.isSafeInteger(val)
                        ? BigInt(val)
                        : typeof val === 'string' && /^-?\d+$/.test(val)
                          ? BigInt(val)
                          : val,
                    z.int64(),
                  )
                  .exactOptional()
                  .openapi({
                    type: 'integer',
                    format: 'int64',
                    description: 'The number of replicas before scaling',
                    example: 1,
                  }),
                to: z
                  .preprocess(
                    (val) =>
                      typeof val === 'number' && Number.isSafeInteger(val)
                        ? BigInt(val)
                        : typeof val === 'string' && /^-?\d+$/.test(val)
                          ? BigInt(val)
                          : val,
                    z.int64(),
                  )
                  .exactOptional()
                  .openapi({
                    type: 'integer',
                    format: 'int64',
                    description: 'The number of replicas after scaling',
                    example: 3,
                  }),
                triggering_metric: z
                  .string()
                  .exactOptional()
                  .openapi({
                    description:
                      'The metric that triggered the scale change. Known values are "cpu", "requests_per_second", "request_duration". For inactivity sleep, "scale_from_zero" and "scale_to_zero" are used.',
                    example: 'cpu',
                  }),
              })
              .openapi({ required: [] }),
          )
          .exactOptional()
          .openapi({ description: 'Map of component names to their scale changes' }),
      })
      .exactOptional()
      .openapi({
        description: 'Autoscaling event details. Only present for autoscaling events.',
        required: [],
      }),
  })
  .openapi({ required: [] })
  .openapi('AppEvent')

