const AppRollbackValidationConditionSchema = z
  .object({
    code: z
      .enum([
        'incompatible_phase',
        'incompatible_result',
        'exceeded_revision_limit',
        'app_pinned',
        'database_config_conflict',
        'region_conflict',
        'static_site_requires_rebuild',
        'image_source_missing_digest',
      ])
      .exactOptional()
      .openapi({
        example: 'exceeded_revision_limit',
        description:
          "A code identifier that represents the failing condition.\n\nFailing conditions:\n  - `incompatible_phase` - indicates that the deployment's phase is not suitable for rollback.\n  - `incompatible_result` - indicates that the deployment's result is not suitable for rollback.\n  - `exceeded_revision_limit` - indicates that the app has exceeded the rollback revision limits for its tier.\n  - `app_pinned` - indicates that there is already a rollback in progress and the app is pinned.\n  - `database_config_conflict` - indicates that the deployment's database config is different than the current config.\n  - `region_conflict` - indicates that the deployment's region differs from the current app region.\n  \nWarning conditions:\n  - `static_site_requires_rebuild` - indicates that the deployment contains at least one static site that will require a rebuild.\n  - `image_source_missing_digest` - indicates that the deployment contains at least one component with an image source that is missing a digest.\n",
      }),
    message: z
      .string()
      .exactOptional()
      .openapi({
        description: 'A human-readable message describing the failing condition.',
        example:
          'the deployment is past the maximum historical revision limit of 0 for the "starter" app tier',
      }),
    components: z
      .array(
        z
          .string()
          .openapi({
            description: 'If applicable, a list of components that are failing the condition.',
          }),
      )
      .exactOptional()
      .openapi({ example: ['www'] }),
  })
  .openapi({ required: [] })
  .openapi('AppRollbackValidationCondition')

