const AppComponentHealthSchema = z
  .object({
    name: z.string().exactOptional().openapi({ example: 'sample_app' }),
    cpu_usage_percent: z.float64().exactOptional().openapi({ example: 30 }),
    memory_usage_percent: z.float64().exactOptional().openapi({ example: 25 }),
    replicas_desired: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({ type: 'integer', format: 'int64', example: 1 }),
    replicas_ready: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({ type: 'integer', format: 'int64', example: 1 }),
    state: z
      .enum(['UNKNOWN', 'HEALTHY', 'UNHEALTHY'])
      .default('UNKNOWN')
      .exactOptional()
      .openapi({ example: 'HEALTHY' }),
  })
  .openapi({ required: [] })
  .openapi('AppComponentHealth')

