const FirewallRuleSchema = z
  .object({
    uuid: z
      .string()
      .regex(/^$|[0-9a-f]{8}\b-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-\b[0-9a-f]{12}/)
      .exactOptional()
      .openapi({
        example: '79f26d28-ea8a-41f2-8ad8-8cfcdd020095',
        description: 'A unique ID for the firewall rule itself.',
      }),
    cluster_uuid: z
      .string()
      .regex(/^$|[0-9a-f]{8}\b-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-\b[0-9a-f]{12}/)
      .exactOptional()
      .openapi({
        example: '9cc10173-e9ea-4176-9dbc-a4cee4c4ff30',
        readOnly: true,
        description: 'A unique ID for the database cluster to which the rule is applied.',
      }),
    type: z
      .enum(['droplet', 'k8s', 'ip_addr', 'tag', 'app'])
      .openapi({
        example: 'droplet',
        description:
          'The type of resource that the firewall rule allows to access the database cluster.',
      }),
    value: z
      .string()
      .openapi({
        example: 'ff2a6c52-5a44-4b63-b99c-0e98e7a63d61',
        description:
          'The ID of the specific resource, the name of a tag applied to a group of resources, or the IP address that the firewall rule allows to access the database cluster.',
      }),
    created_at: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        example: '2019-01-11T18:37:36Z',
        description:
          'A time value given in ISO8601 combined date and time format that represents when the firewall rule was created.',
        readOnly: true,
      }),
    description: z
      .string()
      .exactOptional()
      .openapi({
        example: 'an IP address for local development',
        description: 'A human-readable description of the rule.',
      }),
  })
  .openapi({ required: ['type', 'value'] })
  .openapi('FirewallRule')

