const RsyslogLogsinkSchema = z
  .object({
    server: z
      .string()
      .openapi({
        example: '192.168.0.1',
        description: 'DNS name or IPv4 address of the rsyslog server',
      }),
    port: z
      .int()
      .max(65535)
      .openapi({
        example: 514,
        description: 'The internal port on which the rsyslog server is listening',
      }),
    tls: z
      .boolean()
      .openapi({
        example: false,
        description:
          'Use TLS (as the messages are not filtered and may contain sensitive information, it is highly recommended to set this to true if the remote server supports it)',
      }),
    format: z
      .enum(['rfc5424', 'rfc3164', 'custom'])
      .openapi({
        example: 'rfc5424',
        description:
          'Message format used by the server, this can be either rfc3164 (the old BSD style message format), `rfc5424` (current syslog message format) or custom',
      }),
    logline: z
      .string()
      .exactOptional()
      .openapi({
        example: '<%pri%>%timestamp:::date-rfc3339% %HOSTNAME% %app-name% %msg%',
        description:
          'Conditional (required if `format` == `custom`).\n\nSyslog log line template for a custom format, supporting limited rsyslog style templating (using `%tag%`). Supported tags are: `HOSTNAME`, `app-name`, `msg`, `msgid`, `pri`, `procid`, `structured-data`, `timestamp` and `timestamp:::date-rfc3339`.\n\n---\n**Datadog Integration Example for Non-Mongo clusters**:\n```\nDD_KEY <%pri%>1 %timestamp:::date-rfc3339% %HOSTNAME%.DB_NAME %app-name% - - - %msg%\n```\n- Replace `DD_KEY` with your actual Datadog API key.\n- Replace `DB_NAME` with the actual name of your database cluster.\n- Configure the Server:\n  - US Region: Use `intake.logs.datadoghq.com`\n  - EU Region: Use `tcp-intake.logs.datadoghq.eu`\n- Configure the Port:\n  - US Region: Use port `10516`\n  - EU Region: Use port `443`\n- Enable TLS:\n  - Ensure the TLS checkbox is enabled.\n- Note: This configuration applies to **non-Mongo clusters only**. For **Mongo clusters**, use the `datadog_logsink` integration instead.\n',
      }),
    sd: z
      .string()
      .exactOptional()
      .openapi({
        example: 'TOKEN tag="LiteralValue"',
        description: 'content of the structured data block of rfc5424 message',
      }),
    ca: z
      .string()
      .exactOptional()
      .openapi({
        example: '-----BEGIN CERTIFICATE-----\\n...\\n-----END CERTIFICATE-----\\n',
        description: 'PEM encoded CA certificate',
      }),
    key: z
      .string()
      .exactOptional()
      .openapi({
        example: '-----BEGIN PRIVATE KEY-----\\n...\\n-----END PRIVATE KEY-----\\n',
        description: '(PEM format) client key if the server requires client authentication',
      }),
    cert: z
      .string()
      .exactOptional()
      .openapi({
        example: '-----BEGIN CERTIFICATE-----\\n...\\n-----END CERTIFICATE-----\\n',
        description: '(PEM format) client cert to use',
      }),
  })
  .openapi({ required: ['server', 'port', 'tls', 'format'] })
  .openapi('RsyslogLogsink')

