const PromSampleSchema = z
  .array(z.xor([z.number(), z.string()]))
  .length(2)
  .openapi({
    description:
      'A Prometheus sample as `[timestamp_seconds, value]`. The timestamp is a UNIX epoch float; the value is a string.',
    example: [1620683817, '1'],
  })
