const Checkpoint_2Schema = z
  .object({
    id: z
      .uuid()
      .exactOptional()
      .openapi({
        readOnly: true,
        description: 'The unique ID of the checkpoint.',
        example: '01a0ed98-0a74-75dd-a625-e4856adbc298',
      }),
    name: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The name of the checkpoint. If you do not set one, a name such as `checkpoint-20260929-143559` is generated.',
        example: 'checkpoint-20260929-143559',
      }),
    microvm_id: z
      .uuid()
      .exactOptional()
      .openapi({
        readOnly: true,
        description: 'The ID of the MicroVM the checkpoint was taken from.',
        example: '01a0ed71-4efb-718f-9598-ca9cba942595',
      }),
    microvm_name: z
      .string()
      .exactOptional()
      .openapi({
        readOnly: true,
        description: 'The name of the MicroVM the checkpoint was taken from.',
        example: 'example-microvm',
      }),
    region: z
      .string()
      .exactOptional()
      .openapi({
        readOnly: true,
        description: "The slug of the checkpoint's region.",
        example: 'mkc1',
      }),
    size: MicrovmSizeSchema.exactOptional(),
    status: z
      .enum([
        'CHECKPOINT_CREATING',
        'CHECKPOINT_AVAILABLE',
        'CHECKPOINT_FAILED',
        'CHECKPOINT_DELETING',
        'CHECKPOINT_DELETED',
      ])
      .exactOptional()
      .openapi({
        readOnly: true,
        description:
          "The checkpoint's status. You can create MicroVMs from the checkpoint when it is `CHECKPOINT_AVAILABLE`.",
        example: 'CHECKPOINT_AVAILABLE',
      }),
    memory_bytes: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({
        type: 'integer',
        format: 'int64',
        readOnly: true,
        description: "The stored size of the checkpoint's memory, in bytes.",
        example: 2147483648,
      }),
    disk_bytes: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({
        type: 'integer',
        format: 'int64',
        readOnly: true,
        description: "The stored size of the checkpoint's disk, in bytes.",
        example: 1073741824,
      }),
    created_at: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        readOnly: true,
        description: 'When the checkpoint was created, in ISO 8601 format.',
        example: '2026-09-29T14:35:59Z',
      }),
  })
  .openapi({
    description:
      "A checkpoint of a MicroVM's memory and disk. New MicroVMs created from a checkpoint start from that state.",
    required: [],
  })
  .openapi('Checkpoint_2')

const ExecRequestSchema = z
