const ApiPresetSaveSectionSchema = z
  .enum([
    'PRESET_SAVE_SECTION_UNSPECIFIED',
    'PRESET_SAVE_SECTION_CANDIDATE',
    'PRESET_SAVE_SECTION_METRICS',
    'PRESET_SAVE_SECTION_JUDGE',
    'PRESET_SAVE_SECTION_DATASET',
    'PRESET_SAVE_SECTION_SYSTEM_PROMPT',
  ])
  .default('PRESET_SAVE_SECTION_UNSPECIFIED')
  .openapi({
    description:
      "Sections of an inline evaluation config that can be persisted as a reusable\npreset. Each value names a self-contained group of fields; selecting a\nsection saves exactly the fields it owns and leaves the rest of the preset\nempty so it can be merged with inline values on a future run.\n\n - PRESET_SAVE_SECTION_CANDIDATE: Candidate model identity (`candidate_model_uuid`, `candidate_model_source`,\n`candidate_model_name`) and the non-prompt inference params\n(`temperature`, `stop_token`, `reasoning_effort`).\n - PRESET_SAVE_SECTION_METRICS: The selected `metric_uuids` and the optional `star_metric`.\n - PRESET_SAVE_SECTION_JUDGE: The `judge_model_uuid`.\n - PRESET_SAVE_SECTION_DATASET: The `dataset_uuid`.\n - PRESET_SAVE_SECTION_SYSTEM_PROMPT: The candidate's `system_prompt` only. Independent of CANDIDATE so the\nmodel + params and the prompt can be saved/replayed separately.",
    example: 'PRESET_SAVE_SECTION_UNSPECIFIED',
  })
  .openapi('ApiPresetSaveSection')

