export const postV2AgentsSessionsSessionIdWorkspaceTransfersRoute = createRoute({
  method: 'post',
  path: '/v2/agents/sessions/{session_id}/workspace/transfers',
  tags: ['Harness Runtime'],
  summary: 'Start a staged (large-file) workspace transfer.',
  description:
    'Creates an asynchronous, object-storage-backed transfer for payloads larger than the streaming path supports (> ~50 MiB). Bulk bytes never traverse harness-api: the client PUTs/GETs presigned DO Spaces URLs directly.\n\nSet `direction` to `upload` or `download`.\n- `upload`: responds 201 with `transfer_id` + `part_size`; the client then requests per-part presigned PUT URLs, uploads them to Spaces, and calls `commit`.\n- `download`: responds 202 with `transfer_id`; the client polls GET until `completed` and then fetches `download_url` from Spaces.\n\nUpload and cancel currently return 501 until the sandbox backend RPCs ship; download is live.',
  operationId: 'harness_create_session_workspace_transfer',
  request: {
    params: z.object({
      session_id: z
        .string()
        .openapi({
          param: {
            in: 'path',
            name: 'session_id',
            required: true,
            description: 'The session UUID.',
            schema: { type: 'string', example: 'a1b2c3d4-e5f6-7890-abcd-ef1234567890' },
            example: 'a1b2c3d4-e5f6-7890-abcd-ef1234567890',
          },
          example: 'a1b2c3d4-e5f6-7890-abcd-ef1234567890',
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              direction: z
                .enum(['upload', 'download'])
                .openapi({ description: 'Transfer direction.', example: 'upload' }),
              path: z
                .string()
                .openapi({
                  description:
                    'Workspace-relative path. Destination for upload, source for download. Paths that escape the workspace root are rejected.',
                  example: 'example',
                }),
              is_archive: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'Upload only. When true, the payload is a tar the guest extracts at `path`.',
                  example: true,
                }),
              as_archive: z
                .boolean()
                .exactOptional()
                .openapi({
                  description: 'Download only. When true, `path` is exported as a tar stream.',
                  example: true,
                }),
              size_bytes: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Optional total payload size. Validated against the maximum staged object size (50 GiB); a larger value returns 413.',
                  example: 'example',
                }),
              sha256: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Optional lowercase hex SHA-256 of the full payload. If set on an upload, it must match on commit.',
                  example: 'example',
                }),
            })
            .openapi({ required: ['direction', 'path'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Upload transfer created; proceed to request part upload URLs.',
      content: { 'application/json': { schema: WorkspaceTransferCreatedSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    202: {
      description: 'Download transfer accepted; poll the transfer until completed.',
      content: { 'application/json': { schema: WorkspaceTransferCreatedSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    400: {
      description: 'Missing/invalid direction or path, or invalid JSON.',
      content: { 'application/json': { schema: ErrorSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    401: UnauthorizedResponse,
    402: {
      description: 'The team is blocked by the prepayment gate.',
      content: { 'application/json': { schema: ErrorSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    403: {
      description: 'Path resolves outside the workspace, or the session belongs to another team.',
      content: { 'application/json': { schema: ErrorSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    404: NotFoundResponse,
    409: {
      description: 'Session has no sandbox, or the sandbox is not ready.',
      content: { 'application/json': { schema: ErrorSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    413: {
      description: 'Declared size exceeds the maximum staged object size.',
      content: { 'application/json': { schema: ErrorSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    423: {
      description: 'This session is unavailable; contact support.',
      content: { 'application/json': { schema: ErrorSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    429: TooManyRequestsResponse,
    500: ServerErrorResponse,
    501: {
      description:
        'Staged transfer (or this direction) is not supported by the active sandbox driver.',
      content: { 'application/json': { schema: ErrorSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    502: {
      description: 'Upstream sandbox transfer coordination failed.',
      content: { 'application/json': { schema: ErrorSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    default: UnexpectedErrorResponse,
  },
  security: [{ bearer_auth: ['agent_harness_session:operate'] }],
})

