export const getV2AgentsSessionsSessionIdEventsRoute = createRoute({
  method: 'get',
  path: '/v2/agents/sessions/{session_id}/events',
  tags: ['Harness Runtime'],
  summary: "StreamSessionEvents opens the session's Server-Sent Events feed.",
  description:
    "Opens a `text/event-stream` of the session's canonical events, served by the MARS data plane (OHP).\nEach frame is `event: <type>` plus a `data:` line holding a JSON event envelope; comment lines\n(`: keepalive`) arrive about every 15s and must be ignored. Decode every `data:` with one envelope\nparser and dispatch on the envelope's `type`. Every stream opens with a `stream.state` control frame\n(its `data` is a `stream_state`).\n\nDelivery is at-least-once: clients MUST de-duplicate and order by `event_id` (a ULID), never by\n`seq`. The same path serves two modes:\n  - live attach (default): recent context, then an open stream that stays live until the client\n    disconnects. Pass `Last-Event-ID` (or `cursor`) to resume strictly after the last event the\n    client already rendered, suppressing the last-N context floor.\n  - finite replay (`replay_only=true`): writes a bounded slice of the stored transcript and closes.\n    This is what `doctl agents logs` uses; paginate it with `replay_from`.\n\nOHP serves recent history only (bounded by Kafka retention and an event window); it is not an\narchive. OHP's own errors (404/429/500/503) use the DO-standard JSON `{id, message, request_id}`\nenvelope (cthulhu#179797 / MARSOHS-2065); the 401 comes from the edge.",
  operationId: 'harness_get_session_events',
  request: {
    params: z.object({
      session_id: z
        .string()
        .openapi({
          param: {
            in: 'path',
            name: 'session_id',
            required: true,
            description: 'The session UUID.',
            schema: { type: 'string', example: 'a1b2c3d4-e5f6-7890-abcd-ef1234567890' },
            example: 'a1b2c3d4-e5f6-7890-abcd-ef1234567890',
          },
          example: 'a1b2c3d4-e5f6-7890-abcd-ef1234567890',
        }),
    }),
    query: z.object({
      replay_only: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'replay_only',
            required: false,
            description:
              "Write the selected history and then close the stream, rather than going live. Does not advance the device's delivery cursor, so it never supersedes a live attach from the same device.",
            schema: { type: 'boolean', default: false, example: false },
            example: false,
          },
          example: false,
        }),
      replay_from: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'replay_from',
            required: false,
            description:
              'Event-id pagination cursor for the `replay_only` lane only; return events after this one. There is no last-N floor, so a cursor already at the head yields nothing. Ignored on a live attach.',
            schema: { type: 'string', example: '' },
            example: '',
          },
          example: '',
        }),
      cursor: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'cursor',
            required: false,
            description:
              'Query-param equivalent of `Last-Event-ID`, because a browser EventSource cannot set request headers. Takes precedence over the header when both are present. Live-attach lane only.',
            schema: { type: 'string', example: '' },
            example: '',
          },
          example: '',
        }),
      device_id: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'device_id',
            required: false,
            description:
              'Query-param equivalent of `X-Device-UUID`. Identifies one client install so its delivery cursor and live slot are its own; a second attach from the same device supersedes the first.',
            schema: { type: 'string', example: '' },
            example: '',
          },
          example: '',
        }),
    }),
    headers: z.object({
      'Last-Event-ID': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            in: 'header',
            name: 'Last-Event-ID',
            required: false,
            description:
              'The last event this client rendered (not merely received). Its presence marks the request a reconnect, so OHP serves strictly what follows it with no last-N floor. Persist it only after rendering.',
            schema: { type: 'string', example: '01K9YQ0R2M4A7X' },
            example: '01K9YQ0R2M4A7X',
          },
          example: '01K9YQ0R2M4A7X',
        }),
      'X-Device-UUID': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            in: 'header',
            name: 'X-Device-UUID',
            required: false,
            description: 'A stable per-install device id. See `device_id`.',
            schema: { type: 'string', example: 'd1e2f3a4-b5c6-7890-abcd-ef1234567890' },
            example: 'd1e2f3a4-b5c6-7890-abcd-ef1234567890',
          },
          example: 'd1e2f3a4-b5c6-7890-abcd-ef1234567890',
        }),
    }),
  },
  responses: {
    200: {
      description:
        'An SSE stream. Each frame is `event: <type>` plus a `data:` line holding a JSON event envelope\n(see `stream_event`). The stream opens with a `stream.state` control frame, then events\noldest-first, then either a `stream.state: live` frame (live attach) or end-of-stream\n(`replay_only=true`).',
      content: { 'text/event-stream': { schema: StreamEventSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
        'Cache-Control': {
          description: 'Always no-cache.',
          example: 'no-cache',
          schema: z
            .string()
            .exactOptional()
            .openapi({
              description: 'Always no-cache.',
              example: 'no-cache',
              param: { required: false },
            }),
        },
      }),
    },
    401: UnauthorizedResponse,
    404: {
      description:
        "Unknown session, or a session belonging to another team. The two are deliberately indistinguishable so a caller cannot enumerate other tenants' session ids.",
      content: { 'application/json': { schema: ErrorSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    429: {
      description: 'Attach admission limit reached. Retry after the Retry-After hint.',
      content: { 'application/json': { schema: ErrorSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
        'Retry-After': {
          description: 'Seconds to wait before retrying.',
          example: 2,
          schema: z
            .int()
            .exactOptional()
            .openapi({
              description: 'Seconds to wait before retrying.',
              example: 2,
              param: { required: false },
            }),
        },
      }),
    },
    500: {
      description: 'Internal error.',
      content: { 'application/json': { schema: ErrorSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    503: {
      description:
        "OHP cannot currently establish the caller's authorization or the session's location. Transient; retry after the Retry-After hint.",
      content: { 'application/json': { schema: ErrorSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
        'Retry-After': {
          description: 'Seconds to wait before retrying.',
          example: 2,
          schema: z
            .int()
            .exactOptional()
            .openapi({
              description: 'Seconds to wait before retrying.',
              example: 2,
              param: { required: false },
            }),
        },
      }),
    },
    default: UnexpectedErrorResponse,
  },
  security: [{ bearer_auth: ['agent_harness_session:read'] }],
})

export const getV2AgentsSessionsSessionIdPortForwardPortRoute = createRoute({
  method: 'get',
  path: '/v2/agents/sessions/{session_id}/port-forward/{port}',
  tags: ['Harness Runtime'],
  summary: 'PortForwardSession opens a WebSocket tunnel to a guest TCP port.',
  description:
    "Upgrades the request to a WebSocket and bridges it to one TCP connection on the session sandbox's\nguest `port`. Binary frames carry the opaque byte stream in both directions; the server closes with\na descriptive WebSocket close code when the tunnel ends. This is the raw TCP tunnel; browser clients\nreaching the in-guest OpenHands Agent Server use the ingress URL\n(`GET /v2/agents/sessions/{session_id}/ingress`), which has replaced this bridge for them.\n\nWebSocket is not expressible in OpenAPI; this documents the GET that initiates the upgrade handshake\n(HTTP 101 Switching Protocols). The handler dials the guest before upgrading, so a PAUSED session is\nwoken and served rather than rejected. `port` must be between 1024 and 65535. A request without the\nWebSocket upgrade headers is answered 400 by the handshake layer.",
  operationId: 'harness_get_session_port_forward',
  request: {
    params: z.object({
      session_id: z
        .string()
        .openapi({
          param: {
            in: 'path',
            name: 'session_id',
            required: true,
            description: 'The session UUID.',
            schema: { type: 'string', example: 'a1b2c3d4-e5f6-7890-abcd-ef1234567890' },
            example: 'a1b2c3d4-e5f6-7890-abcd-ef1234567890',
          },
          example: 'a1b2c3d4-e5f6-7890-abcd-ef1234567890',
        }),
      port: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1024).max(65535),
        )
        .openapi({
          param: {
            in: 'path',
            name: 'port',
            required: true,
            description: 'The guest TCP port to connect to. Must be between 1024 and 65535.',
            schema: { type: 'integer', minimum: 1024, maximum: 65535, example: 8000 },
            example: 8000,
          },
          example: 8000,
        }),
    }),
  },
  responses: {
    101: {
      description:
        'Switching Protocols. The WebSocket handshake succeeded and the connection is now a binary tunnel to the guest port.',
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    400: {
      description:
        'The request is not a valid WebSocket upgrade (missing Upgrade/Connection headers). Returned by the handshake layer as plain text.',
      content: { 'text/plain': { schema: z.string().openapi({ example: 'Bad Request' }) } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    401: UnauthorizedResponse,
    402: {
      description: 'The team is blocked by the prepayment gate.',
      content: { 'application/json': { schema: ErrorSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    403: {
      description: 'The port is outside 1024-65535, or the session belongs to another team.',
      content: { 'application/json': { schema: ErrorSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    404: NotFoundResponse,
    409: {
      description: 'The session has no sandbox.',
      content: { 'application/json': { schema: ErrorSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    423: {
      description: 'This session is unavailable; contact support.',
      content: { 'application/json': { schema: ErrorSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    429: TooManyRequestsResponse,
    500: ServerErrorResponse,
    502: {
      description: 'Could not reach the guest port (nothing listening, or the guest dial failed).',
      content: { 'application/json': { schema: ErrorSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    default: UnexpectedErrorResponse,
  },
  security: [{ bearer_auth: ['agent_harness_session:operate'] }],
})

export const getV2AgentsSessionsSessionIdIngressRoute = createRoute({
  method: 'get',
  path: '/v2/agents/sessions/{session_id}/ingress',
  tags: ['Harness Runtime'],
  summary: "GetIngressURL returns the public HTTPS URL of the session's OpenHands Agent Server.",
  description:
    "Publishes the URL on first call and returns it. Idempotent while the session runs: the same URL is\nreturned until the session is paused, locked or rolled back, after which the next call returns a new\nhostname (pause and lock revoke the URL; rollback moves the session to a new sandbox, so re-fetch\nafter resume, unlock or rollback). The URL fronts guest port 8000 (the OpenHands Agent Server,\nHTTP + WebSocket) and replaces the port-forward bridge for browser clients. Requests to the URL carry\nthe caller's DO token as a Bearer header. Poll until `state` is INGRESS_URL_STATE_READY; there is no\nfailed state. Only OpenHands sessions support ingress, and it is gated per team.",
  operationId: 'harness_get_session_ingress',
  request: {
    params: z.object({
      session_id: z
        .string()
        .openapi({
          param: {
            in: 'path',
            name: 'session_id',
            required: true,
            description: 'The session UUID.',
            schema: { type: 'string', example: 'a1b2c3d4-e5f6-7890-abcd-ef1234567890' },
            example: 'a1b2c3d4-e5f6-7890-abcd-ef1234567890',
          },
          example: 'a1b2c3d4-e5f6-7890-abcd-ef1234567890',
        }),
    }),
  },
  responses: {
    200: {
      description: 'A successful response.',
      content: { 'application/json': { schema: GetIngressUrlResponseSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    401: UnauthorizedResponse,
    403: {
      description: 'Session belongs to another team.',
      content: { 'application/json': { schema: ErrorSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    404: NotFoundResponse,
    409: {
      description: 'Session is not running.',
      content: { 'application/json': { schema: ErrorSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    423: {
      description: 'This session is unavailable; contact support.',
      content: { 'application/json': { schema: ErrorSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    429: TooManyRequestsResponse,
    500: ServerErrorResponse,
    501: {
      description: 'Public ingress is not supported for this agent kind or sandbox substrate.',
      content: { 'application/json': { schema: ErrorSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    default: UnexpectedErrorResponse,
  },
  security: [{ bearer_auth: ['agent_harness_session:read'] }],
})

