export const postV2AgentsTriggersRoute = createRoute({
  method: 'post',
  path: '/v2/agents/triggers',
  tags: ['Harness Runtime'],
  summary: 'CreateTrigger creates a webhook or cron trigger.',
  description:
    'Validation is synchronous, so a mistake is a 400/409 at creation, not a silent miss at the first\nfire. Exactly one of `webhook` / `cron` must be present and match `kind`. kind=cron forbids a\n`webhook` block and requires a parseable `cron.cron_expr` and a valid IANA `cron.timezone`.\nsession_mode=fresh requires `session_template` (a well-formed agents.yaml Agent manifest) and\nforbids `bound_session_id`; session_mode=reuse requires `bound_session_id` (an existing team-owned\nsession) and forbids `session_template`. `output.mode` selects the destination block (email/slack),\nwhich is stored encrypted. `name` must be unique per team among non-deleted triggers.\n\nFor webhook triggers the response includes `webhook_secret` exactly ONCE - it is never returned\nagain. Cron triggers return no secret and carry a computed `trigger.cron.next_run_at`. The team and\nuser identity are taken from the authenticated principal, never the body.',
  operationId: 'harness_create_trigger',
  request: {
    body: {
      description: 'The trigger to create.',
      content: { 'application/json': { schema: CreateTriggerRequestSchema } },
      required: true,
    },
  },
  responses: {
    201: {
      description:
        'Trigger created. `webhook_secret` present for webhook triggers only, shown once.',
      content: { 'application/json': { schema: CreateTriggerResponseSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    400: {
      description:
        'Validation failed (bad manifest/cron/timezone, kind/block/mode mismatch, provider on cron, payload placeholder in a cron prompt, invalid email, etc.).',
      content: { 'application/json': { schema: ErrorSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    401: UnauthorizedResponse,
    403: {
      description:
        'The caller is not permitted to create the backing agent config for this trigger.',
      content: { 'application/json': { schema: ErrorSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    409: {
      description: 'A non-deleted trigger with this name already exists for the team.',
      content: { 'application/json': { schema: ErrorSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    422: {
      description: "The team's trigger limit has been reached.",
      content: { 'application/json': { schema: ErrorSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    429: TooManyRequestsResponse,
    500: ServerErrorResponse,
    502: {
      description: 'The backing agent config service returned an unexpected error.',
      content: { 'application/json': { schema: ErrorSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    503: {
      description:
        'An upstream dependency needed to validate the trigger is temporarily unavailable; retry.',
      content: { 'application/json': { schema: ErrorSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    default: UnexpectedErrorResponse,
  },
  security: [{ bearer_auth: ['agent_harness_session:create'] }],
})

