export const getV2AppsAppIdDeploymentsRoute = createRoute({
  method: 'get',
  path: '/v2/apps/{app_id}/deployments',
  tags: ['Apps'],
  summary: 'List App Deployments',
  description: 'List all deployments of an app.',
  operationId: 'apps_list_deployments',
  request: {
    params: z.object({ app_id: AppIdParamsSchema }),
    query: z.object({
      page: PageParamsSchema,
      per_page: ParametersPerPageParamsSchema,
      deployment_types: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(
            z.enum([
              'MANUAL',
              'DEPLOY_ON_PUSH',
              'MAINTENANCE',
              'MANUAL_ROLLBACK',
              'AUTO_ROLLBACK',
              'UPDATE_DATABASE_TRUSTED_SOURCES',
              'AUTOSCALED',
            ]),
          ),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'deployment_types',
            description:
              "Optional. Filter deployments by deployment_type\n  - MANUAL: manual deployment\n  - DEPLOY_ON_PUSH: deployment triggered by a push to the app's repository\n  - MAINTENANCE: deployment for maintenance purposes\n  - MANUAL_ROLLBACK: manual revert to a previous deployment\n  - AUTO_ROLLBACK: automatic revert to a previous deployment\n  - UPDATE_DATABASE_TRUSTED_SOURCES: update database trusted sources\n  - AUTOSCALED: deployment that has been autoscaled",
            in: 'query',
            required: false,
            schema: {
              type: 'array',
              items: {
                type: 'string',
                enum: [
                  'MANUAL',
                  'DEPLOY_ON_PUSH',
                  'MAINTENANCE',
                  'MANUAL_ROLLBACK',
                  'AUTO_ROLLBACK',
                  'UPDATE_DATABASE_TRUSTED_SOURCES',
                  'AUTOSCALED',
                ],
              },
            },
            example: ['MANUAL', 'AUTOSCALED'],
          },
        }),
    }),
  },
  responses: {
    200: ExistingDeploymentsResponse,
    401: UnauthorizedResponse,
    404: NotFoundResponse,
    429: TooManyRequestsResponse,
    500: ServerErrorResponse,
    default: UnexpectedErrorResponse,
  },
  security: [{ bearer_auth: ['app:read'] }],
})

