export const deleteV2CdnEndpointsCdnIdCacheRoute = createRoute({
  method: 'delete',
  path: '/v2/cdn/endpoints/{cdn_id}/cache',
  tags: ['CDN Endpoints'],
  summary: 'Purge the Cache for an Existing CDN Endpoint',
  description:
    "To purge cached content from a CDN endpoint, send a DELETE request to\n`/v2/cdn/endpoints/$ENDPOINT_ID/cache`. The body of the request should include\na `files` attribute containing a list of cached file paths to be purged. A\npath may be for a single file or may contain a wildcard (`*`) to recursively\npurge all files under a directory. When only a wildcard is provided, all cached \nfiles will be purged. There is a rate limit of 50 files per 20 seconds that can \nbe purged. CDN endpoints have a rate limit of 5 requests per 10 seconds. \nPurging files using a wildcard path counts as a single request against the API's \nrate limit. Two identical purge requests cannot be sent at the same time.\n",
  operationId: 'cdn_purge_cache',
  request: {
    params: z.object({ cdn_id: CdnEndpointIdParamsSchema }),
    body: { content: { 'application/json': { schema: PurgeCacheSchema } }, required: true },
  },
  responses: {
    204: NoContentResponse,
    401: UnauthorizedResponse,
    404: NotFoundResponse,
    429: TooManyRequestsResponse,
    500: ServerErrorResponse,
    default: UnexpectedErrorResponse,
  },
  security: [{ bearer_auth: ['cdn:delete'] }],
})

