export const putV2DatabasesDatabaseClusterUuidOnlineMigrationRoute = createRoute({
  method: 'put',
  path: '/v2/databases/{database_cluster_uuid}/online-migration',
  tags: ['Databases'],
  summary: 'Start an Online Migration',
  description:
    'To start an online migration, send a PUT request to `/v2/databases/$DATABASE_ID/online-migration` endpoint. Migrating a cluster establishes a connection with an existing cluster and replicates its contents to the target cluster. Online migration is only available for MySQL, PostgreSQL, Caching, and Valkey clusters.\nIf the existing database is continuously being written to,  the migration process will continue for up to two weeks unless it is manually stopped. Online migration is only available for [MySQL](https://docs.digitalocean.com/products/databases/mysql/how-to/migrate/#:~:text=To%20migrate%20a%20MySQL%20database,then%20select%20Set%20Up%20Migration),  [PostgreSQL](https://docs.digitalocean.com/products/databases/postgresql/how-to/migrate/),  [Caching](https://docs.digitalocean.com/products/databases/redis/how-to/migrate/), and [Valkey](https://docs.digitalocean.com/products/databases/valkey/how-to/migrate/) clusters. ',
  operationId: 'databases_update_onlineMigration',
  request: {
    params: z.object({ database_cluster_uuid: DatabaseClusterUuidParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: SourceDatabaseSchema,
          example: {
            source: {
              host: 'source-db.example.com',
              dbname: 'defaultdb',
              port: 25060,
              username: 'doadmin',
              password: 'example_password',
            },
            disable_ssl: false,
            ignore_dbs: ['db0', 'db1'],
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: OnlineMigrationResponse,
    401: UnauthorizedResponse,
    404: NotFoundResponse,
    429: TooManyRequestsResponse,
    500: ServerErrorResponse,
    default: UnexpectedErrorResponse,
  },
  security: [{ bearer_auth: ['database:update'] }],
})

