export const postV2DatabasesDatabaseClusterUuidReplicasRoute = createRoute({
  method: 'post',
  path: '/v2/databases/{database_cluster_uuid}/replicas',
  tags: ['Databases'],
  summary: 'Create a Read-only Replica',
  description:
    "To create a read-only replica for a PostgreSQL or MySQL database cluster, send a POST request to `/v2/databases/$DATABASE_ID/replicas` specifying the name it should be given, the size of the node to be used, and the region where it will be located.\n\n**Note**: Read-only replicas are not supported for Caching or Valkey clusters.\n\nThe response will be a JSON object with a key called `replica`. The value of this will be an object that contains the standard attributes associated with a database replica. The initial value of the read-only replica's `status` attribute will be `forking`. When the replica is ready to receive traffic, this will transition to `active`.",
  operationId: 'databases_create_replica',
  request: {
    params: z.object({ database_cluster_uuid: DatabaseClusterUuidParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: DatabaseReplicaSchema.openapi({ required: ['name', 'size'] }),
          examples: {
            'Create a Read-only Replica': {
              value: {
                name: 'read-nyc3-01',
                region: 'nyc3',
                size: 'db-s-2vcpu-4gb',
                storage_size_mib: 61440,
              },
            },
            'Create a Read-only Replica with service CNAMEs': {
              value: {
                name: 'read-nyc3-01',
                region: 'nyc3',
                size: 'db-s-2vcpu-4gb',
                storage_size_mib: 61440,
                do_settings: {
                  service_cnames: ['replica-db.example.com', 'read-replica.myapp.io'],
                },
              },
            },
          },
        },
      },
    },
  },
  responses: {
    201: DatabaseReplicaResponse,
    401: UnauthorizedResponse,
    404: NotFoundResponse,
    429: TooManyRequestsResponse,
    500: ServerErrorResponse,
    default: UnexpectedErrorResponse,
  },
  security: [{ bearer_auth: ['database:create'] }],
})

