export const postV2DatabasesDatabaseClusterUuidUsersRoute = createRoute({
  method: 'post',
  path: '/v2/databases/{database_cluster_uuid}/users',
  tags: ['Databases'],
  summary: 'Add a Database User',
  description:
    'To add a new database user, send a POST request to `/v2/databases/$DATABASE_ID/users`\nwith the desired username.\n\nNote: User management is not supported for Caching or Valkey clusters.\n\nWhen adding a user to a MySQL cluster, additional options can be configured in the\n`mysql_settings` object.\n\nWhen adding a user to a PostgreSQL cluster, additional options can be configured in\nthe `settings` object (for example, `pg_allow_replication`). When\n`pg_allow_replication` is omitted, it defaults to `false`.\n\nWhen adding a user to a Kafka cluster, additional options can be configured in\nthe `settings` object.\n\nWhen adding a user to a MongoDB cluster, additional options can be configured in\nthe `settings.mongo_user_settings` object.\n\nThe response will be a JSON object with a key called `user`. The value of this will be an\nobject that contains the standard attributes associated with a database user including\nits randomly generated password.\n',
  operationId: 'databases_add_user',
  request: {
    params: z.object({ database_cluster_uuid: DatabaseClusterUuidParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: DatabaseUserSchema.and(
            z
              .object({
                readonly: z
                  .boolean()
                  .exactOptional()
                  .openapi({
                    example: true,
                    description:
                      '(To be deprecated: use settings.mongo_user_settings.role instead for access controls to MongoDB databases). \nFor MongoDB clusters, set to `true` to create a read-only user.\nThis option is not currently supported for other database engines.\n           \n',
                  }),
              })
              .openapi({ required: [] }),
          ),
          examples: {
            'Add New User': { value: { name: 'app-01' } },
            'Add New User with MySQL Auth Plugin': {
              value: { name: 'app-02', mysql_settings: { auth_plugin: 'mysql_native_password' } },
            },
            'Add New Read Only User (MongoDB Only)': {
              value: { name: 'my-readonly', readonly: true },
            },
            'Add New User that is restricted to a database (MongoDB Only)': {
              value: {
                name: 'my-readWrite',
                settings: {
                  mongo_user_settings: { databases: ['my-db', 'my-db-2'], role: 'readWrite' },
                },
              },
            },
            'Add New User for Postgres with replication rights': {
              value: { name: 'app-02', settings: { pg_allow_replication: true } },
            },
            'Add New User with Kafka ACLs': {
              value: {
                name: 'app-03',
                settings: {
                  acl: [
                    { permission: 'produceconsume', topic: 'customer-events' },
                    { permission: 'produce', topic: 'customer-events.*' },
                    { permission: 'consume', topic: 'customer-events' },
                  ],
                },
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    201: UserResponse,
    401: UnauthorizedResponse,
    404: NotFoundResponse,
    429: TooManyRequestsResponse,
    500: ServerErrorResponse,
    default: UnexpectedErrorResponse,
  },
  security: [{ bearer_auth: ['database:create'] }],
})

