export const putV2DatabasesDatabaseClusterUuidUsersUsernameRoute = createRoute({
  method: 'put',
  path: '/v2/databases/{database_cluster_uuid}/users/{username}',
  tags: ['Databases'],
  summary: 'Update a Database User',
  description:
    'To update an existing database user, send a PUT request to `/v2/databases/$DATABASE_ID/users/$USERNAME`\nwith the desired settings.\n\n**Note**: only `settings` can be updated via this type of request. If you wish to change the name of a user,\nyou must recreate a new user.\n\nFor PostgreSQL clusters, you can update `settings.pg_allow_replication` to enable or\ndisable replication privileges for the user. When omitted, the value defaults to `false`.\n\nFor Kafka and OpenSearch clusters, additional options can be configured in the\n`settings` object (for example, topic or index ACLs).\n\nUpdating users is supported for PostgreSQL, Kafka, and OpenSearch clusters. For\nother engines, the request returns a 422. MongoDB roles and database access are\nset with `settings.mongo_user_settings` when creating a user and cannot be\nchanged afterward; recreate the user to apply different roles or databases.\n\nThe response will be a JSON object with a key called `user`. The value of this will be an\nobject that contains the name of the updated database user, along with the `settings` object that\nhas been updated.\n',
  operationId: 'databases_update_user',
  request: {
    params: z.object({
      database_cluster_uuid: DatabaseClusterUuidParamsSchema,
      username: UsernameParamsSchema,
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({ settings: UserSettingsUpdateSchema.exactOptional() })
            .openapi({ required: [] })
            .openapi({ required: ['settings'] }),
          examples: {
            'Update User Postgres Replication Rights': {
              value: { settings: { pg_allow_replication: true } },
            },
            'Update User Kafka ACLs': {
              value: {
                settings: {
                  acl: [
                    {
                      id: 'acl128aaaa99239',
                      permission: 'produceconsume',
                      topic: 'customer-events',
                    },
                    { id: 'acl293098flskdf', permission: 'produce', topic: 'customer-events.*' },
                    { id: 'acl128ajei20123', permission: 'consume', topic: 'customer-events' },
                  ],
                },
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    201: UserResponse,
    401: UnauthorizedResponse,
    404: NotFoundResponse,
    422: UnprocessableEntityResponse,
    429: TooManyRequestsResponse,
    500: ServerErrorResponse,
    default: UnexpectedErrorResponse,
  },
  security: [{ bearer_auth: ['database:update'] }],
})

