export const getV2DedicatedInferencesDedicatedInferenceIdAcceleratorsRoute = createRoute({
  method: 'get',
  path: '/v2/dedicated-inferences/{dedicated_inference_id}/accelerators',
  tags: ['Dedicated Inference'],
  summary: 'List Dedicated Inference Accelerators',
  description:
    'List all accelerators (GPUs) in use by a Dedicated Inference instance. Send a\nGET request to `/v2/dedicated-inferences/{dedicated_inference_id}/accelerators`.\nOptionally filter by slug and use page/per_page for pagination.\n',
  operationId: 'dedicatedInferences_list_accelerators',
  request: {
    params: z.object({
      dedicated_inference_id: z
        .uuid()
        .openapi({
          param: {
            name: 'dedicated_inference_id',
            in: 'path',
            required: true,
            description: 'A unique identifier for a Dedicated Inference instance.',
            schema: { type: 'string', format: 'uuid' },
            example: '6b5c619c-359c-44ca-87e2-47e98170c01d',
          },
        }),
    }),
    query: z.object({
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(200),
        )
        .default(20)
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            in: 'query',
            required: false,
            description: 'Number of items returned per page',
            schema: { type: 'integer', minimum: 1, default: 20, maximum: 200 },
            example: 20,
          },
        }),
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            in: 'query',
            required: false,
            description: "Which 'page' of paginated results to return.",
            schema: { type: 'integer', minimum: 1, default: 1 },
            example: 1,
          },
        }),
      slug: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'slug',
            in: 'query',
            required: false,
            description: 'Filter accelerators by GPU slug.',
            schema: { type: 'string' },
            example: 'gpu-mi300x1-192gb',
          },
        }),
    }),
  },
  responses: {
    200: AcceleratorsListResponse,
    401: UnauthorizedResponse,
    404: NotFoundResponse,
    429: TooManyRequestsResponse,
    500: ServerErrorResponse,
    default: UnexpectedErrorResponse,
  },
  security: [{ bearer_auth: ['dedicated_inference:read'] }],
})

