export const postV2DomainsDomainNameRecordsRoute = createRoute({
  method: 'post',
  path: '/v2/domains/{domain_name}/records',
  tags: ['Domain Records'],
  summary: 'Create a New Domain Record',
  description:
    'To create a new record to a domain, send a POST request to\n`/v2/domains/$DOMAIN_NAME/records`.\n\nThe request must include all of the required fields for the domain record type\nbeing added.\n\nSee the [attribute table](#tag/Domain-Records) for details regarding record\ntypes and their respective required attributes.\n',
  operationId: 'domains_create_record',
  request: {
    params: z.object({ domain_name: DomainNameParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .union([
              DomainRecordASchema,
              DomainRecordAaaaSchema,
              DomainRecordCaaSchema,
              DomainRecordCnameSchema,
              DomainRecordMxSchema,
              DomainRecordNsSchema,
              DomainRecordSoaSchema,
              DomainRecordSrvSchema,
              DomainRecordTxtSchema,
            ])
            .openapi({
              discriminator: {
                propertyName: 'type',
                mapping: {
                  A: '#/components/schemas/domain_record_a',
                  AAAA: '#/components/schemas/domain_record_aaaa',
                  CAA: '#/components/schemas/domain_record_caa',
                  CNAME: '#/components/schemas/domain_record_cname',
                  MX: '#/components/schemas/domain_record_mx',
                  NS: '#/components/schemas/domain_record_ns',
                  SOA: '#/components/schemas/domain_record_soa',
                  SRV: '#/components/schemas/domain_record_srv',
                  TXT: '#/components/schemas/domain_record_txt',
                },
              },
            }),
          example: {
            type: 'A',
            name: 'www',
            data: '162.10.66.0',
            priority: null,
            port: null,
            ttl: 1800,
            weight: null,
            flags: null,
            tag: null,
          },
        },
      },
    },
  },
  responses: {
    201: CreatedDomainRecordResponse,
    401: UnauthorizedResponse,
    404: NotFoundResponse,
    429: TooManyRequestsResponse,
    500: ServerErrorResponse,
    default: UnexpectedErrorResponse,
  },
  security: [{ bearer_auth: ['domain:create'] }, { bearer_auth: ['domain:update'] }],
})

