export const postV2FirewallsRoute = createRoute({
  method: 'post',
  path: '/v2/firewalls',
  tags: ['Firewalls'],
  summary: 'Create a New Firewall',
  description:
    'To create a new firewall, send a POST request to `/v2/firewalls`. The request\nmust contain at least one inbound or outbound access rule.\n',
  operationId: 'firewalls_create',
  request: {
    body: {
      content: {
        'application/json': {
          schema: FirewallSchema.and(
            z
              .unknown()
              .superRefine((val, ctx) => {
                if (typeof val === 'object' && val !== null && !Array.isArray(val)) {
                  if (!Object.hasOwn(val, 'name')) {
                    ctx.addIssue({ code: 'custom' })
                  }
                }
              })
              .openapi({ required: ['name'] }),
          ).and(
            z.union([
              z
                .unknown()
                .superRefine((val, ctx) => {
                  if (typeof val === 'object' && val !== null && !Array.isArray(val)) {
                    if (!Object.hasOwn(val, 'inbound_rules')) {
                      ctx.addIssue({ code: 'custom' })
                    }
                  }
                })
                .openapi({ title: 'Inbound Rules', required: ['inbound_rules'] }),
              z
                .unknown()
                .superRefine((val, ctx) => {
                  if (typeof val === 'object' && val !== null && !Array.isArray(val)) {
                    if (!Object.hasOwn(val, 'outbound_rules')) {
                      ctx.addIssue({ code: 'custom' })
                    }
                  }
                })
                .openapi({ title: 'Outbound Rules', required: ['outbound_rules'] }),
            ]),
          ),
          example: {
            name: 'firewall',
            inbound_rules: [
              {
                protocol: 'tcp',
                ports: '80',
                action: 'allow',
                sources: { load_balancer_uids: ['4de7ac8b-495b-4884-9a69-1050c6793cd6'] },
              },
              {
                protocol: 'tcp',
                ports: '22',
                action: 'allow',
                sources: { tags: ['gateway'], addresses: ['18.0.0.0/8'] },
              },
            ],
            outbound_rules: [
              {
                protocol: 'tcp',
                ports: '80',
                action: 'allow',
                destinations: { addresses: ['0.0.0.0/0', '::/0'] },
              },
            ],
            droplet_ids: [8043964],
          },
        },
      },
    },
  },
  responses: {
    202: CreateFirewallResponseResponse,
    400: BadRequestResponse,
    401: UnauthorizedResponse,
    429: TooManyRequestsResponse,
    500: ServerErrorResponse,
    default: UnexpectedErrorResponse,
  },
  security: [{ bearer_auth: ['firewall:create'] }],
})

