export const putV2FirewallsFirewallIdRoute = createRoute({
  method: 'put',
  path: '/v2/firewalls/{firewall_id}',
  tags: ['Firewalls'],
  summary: 'Update a Firewall',
  description:
    'To update the configuration of an existing firewall, send a PUT request to\n`/v2/firewalls/$FIREWALL_ID`. The request should contain a full representation\nof the firewall including existing attributes. **Note that any attributes that\nare not provided will be reset to their default values.**\n<br><br>You must have read access (e.g. `droplet:read`) to all resources attached\nto the firewall to successfully update the firewall.\n',
  operationId: 'firewalls_update',
  request: {
    params: z.object({ firewall_id: FirewallIdParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: FirewallSchema.and(
            z.union([
              z
                .unknown()
                .superRefine((val, ctx) => {
                  if (typeof val === 'object' && val !== null && !Array.isArray(val)) {
                    if (!Object.hasOwn(val, 'inbound_rules')) {
                      ctx.addIssue({ code: 'custom' })
                    }
                  }
                })
                .openapi({ title: 'Inbound Rules', required: ['inbound_rules'] }),
              z
                .unknown()
                .superRefine((val, ctx) => {
                  if (typeof val === 'object' && val !== null && !Array.isArray(val)) {
                    if (!Object.hasOwn(val, 'outbound_rules')) {
                      ctx.addIssue({ code: 'custom' })
                    }
                  }
                })
                .openapi({ title: 'Outbound Rules', required: ['outbound_rules'] }),
            ]),
          ).openapi({ required: ['name'] }),
          example: {
            name: 'frontend-firewall',
            inbound_rules: [
              {
                protocol: 'tcp',
                ports: '8080',
                action: 'allow',
                sources: { load_balancer_uids: ['4de7ac8b-495b-4884-9a69-1050c6793cd6'] },
              },
              {
                protocol: 'tcp',
                ports: '22',
                action: 'allow',
                sources: { tags: ['gateway'], addresses: ['18.0.0.0/8'] },
              },
            ],
            outbound_rules: [
              {
                protocol: 'tcp',
                ports: '8080',
                action: 'allow',
                destinations: { addresses: ['0.0.0.0/0', '::/0'] },
              },
            ],
            droplet_ids: [8043964],
            tags: ['frontend'],
          },
        },
      },
    },
  },
  responses: {
    200: PutFirewallResponseResponse,
    400: BadRequestResponse,
    401: UnauthorizedResponse,
    404: NotFoundResponse,
    429: TooManyRequestsResponse,
    500: ServerErrorResponse,
    default: UnexpectedErrorResponse,
  },
  security: [{ bearer_auth: ['firewall:update'] }],
})

