export const postV2FloatingIpsFloatingIpActionsRoute = createRoute({
  method: 'post',
  path: '/v2/floating_ips/{floating_ip}/actions',
  tags: ['Floating IP Actions'],
  summary: 'Initiate a Floating IP Action',
  description:
    'To initiate an action on a floating IP send a POST request to\n`/v2/floating_ips/$FLOATING_IP/actions`. In the JSON body to the request,\nset the `type` attribute to on of the supported action types:\n\n| Action     | Details\n|------------|--------\n| `assign`   | Assigns a floating IP to a Droplet\n| `unassign` | Unassign a floating IP from a Droplet\n',
  operationId: 'floatingIPsAction_post',
  request: {
    params: z.object({ floating_ip: FloatingIpParamsSchema }),
    body: {
      description:
        'The `type` attribute set in the request body will specify the action that\nwill be taken on the floating IP.\n',
      content: {
        'application/json': {
          schema: z
            .union([FloatingIpActionUnassignSchema, FloatingIpActionAssignSchema])
            .openapi({
              discriminator: {
                propertyName: 'type',
                mapping: {
                  unassign: '#/components/schemas/floating_ip_action_unassign',
                  assign: '#/components/schemas/floating_ip_action_assign',
                },
              },
            }),
        },
      },
    },
  },
  responses: {
    201: FloatingIpActionResponse,
    401: UnauthorizedResponse,
    404: NotFoundResponse,
    429: TooManyRequestsResponse,
    500: ServerErrorResponse,
    default: UnexpectedErrorResponse,
  },
  security: [{ bearer_auth: ['reserved_ip:update'] }],
})

