export const getV2ImagesImageIdRoute = createRoute({
  method: 'get',
  path: '/v2/images/{image_id}',
  tags: ['Images'],
  summary: 'Retrieve an Existing Image',
  description:
    'To retrieve information about an image, send a `GET` request to\n`/v2/images/$IDENTIFIER`.\n',
  operationId: 'images_get',
  request: {
    params: z.object({
      image_id: ((schema) =>
        z.union([
          z.preprocess(
            (val) =>
              typeof val === 'string' &&
              /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
              (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                ? Number(val)
                : val,
            schema,
          ),
          schema,
        ]))(z.union([z.int(), z.string()])).openapi({
        param: {
          in: 'path',
          name: 'image_id',
          description:
            'A unique number (id) or string (slug) used to identify and reference a\nspecific image.\n\n**Public** images can be identified by image `id` or `slug`.\n\n**Private** images *must* be identified by image `id`.\n',
          required: true,
          schema: { anyOf: [{ type: 'integer' }, { type: 'string' }] },
          examples: {
            byId: { summary: 'Retrieve a public or private image by id', value: 62137902 },
            bySlug: { summary: 'Retrieve a public image by slug', value: 'ubuntu-16-04-x64' },
          },
        },
      }),
    }),
  },
  responses: {
    200: ExistingImageResponse,
    401: UnauthorizedResponse,
    404: NotFoundResponse,
    429: TooManyRequestsResponse,
    500: ServerErrorResponse,
    default: UnexpectedErrorResponse,
  },
  security: [{ bearer_auth: ['image:read'] }],
})

