export const postV2ImagesImageIdAccountTransferRoute = createRoute({
  method: 'post',
  path: '/v2/images/{image_id}/account_transfer',
  tags: ['Images'],
  summary: 'Initiate an Image Account Transfer',
  description:
    "To initiate an account transfer for an image, send a POST request to\n`/v2/images/$IMAGE_ID/account_transfer`.\n\nOnly snapshot images may be transferred by this endpoint to another account.\n\nAn image account transfer always has exactly one recipient, specified in the request body.\nThe recipient can be one of the following:\n\n* A DigitalOcean account, denoted by `recipient_email` in the request body.\nThe recipient will receive an email with instructions to accept the transfer.\nOnce the recipient accepts the transfer, the image will be moved to their\naccount.\n\n* A DigitalOcean team, denoted by `recipient_uuid` in the request body. If the\nuser has sufficient permissions in the recipient team, the transfer will be\nautomatically accepted and the image will be moved to the recipient team's\naccount. Otherwise, the transfer will be pending until a user with sufficient\npermissions in the recipient team accepts the transfer.\n",
  operationId: 'images_post_account_transfer_create',
  request: {
    params: z.object({ image_id: ImageIdParamsSchema }),
    body: {
      content: { 'application/json': { schema: ImagesPostAccountTransferCreateSchema } },
      required: true,
    },
  },
  responses: {
    201: ImagesPostAccountTransferCreatedResponse,
    400: BadRequestResponse,
    401: UnauthorizedResponse,
    404: NotFoundResponse,
    429: TooManyRequestsResponse,
    500: ServerErrorResponse,
    default: UnexpectedErrorResponse,
  },
  security: [{ bearer_auth: ['image:update', 'image:delete'] }],
})

