export const postV2MicrovmsRoute = createRoute({
  method: 'post',
  path: '/v2/microvms',
  tags: ['MicroVMs [Public Preview]'],
  summary: 'Create a MicroVM',
  description:
    'To create a MicroVM, send a POST request to `/v2/microvms`.\n\n`name` and `source` are required. Set `source.oci_ref` to create the MicroVM from a\n`linux/amd64` container image, or `source.checkpoint_id` to create it from a checkpoint.\nWith `oci_ref`, `region` and `size` are also required.\n\nA MicroVM created from an image is returned with `state` set to `creating`. Poll\n`GET /v2/microvms/{microvm_id}` until `state` is `running`. A MicroVM created from a\ncheckpoint is usually returned already `running`.\n\nAll settings are fixed at creation. There is no update endpoint.\n',
  operationId: 'microvms_create',
  request: {
    body: {
      content: {
        'application/json': {
          schema: MicrovmCreateSchema,
          examples: {
            'From a Container Image': {
              value: {
                name: 'example-microvm',
                region: 'mkc1',
                size: { cpu: 1, memory: 2048 },
                source: { oci_ref: 'docker.io/library/nginx:latest' },
                http_port: 80,
                http_protocol: 'http',
                auto_pause: { idle_timeout: '5m' },
                tags: ['example'],
              },
            },
            'From a Checkpoint': {
              value: {
                name: 'example-from-checkpoint',
                source: { checkpoint_id: '01a0ed98-0a74-75dd-a625-e4856adbc298' },
              },
            },
            'In a VPC Network': {
              value: {
                name: 'example-vpc-microvm',
                region: 'mkc1',
                size: { cpu: 2, memory: 4096 },
                source: { oci_ref: 'docker.io/library/nginx:latest' },
                http_port: 80,
                networking: 'vpc',
                vpc_uuid: '5a4981aa-9653-4bd1-bef5-d6bff52042e4',
                environment: { APP_ENV: 'production' },
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    201: MicrovmCreatedResponse,
    400: ErrorsBadRequestResponse,
    401: UnauthorizedResponse,
    403: ErrorsForbiddenResponse,
    429: TooManyRequestsResponse,
    500: ServerErrorResponse,
    default: UnexpectedErrorResponse,
  },
  security: [{ bearer_auth: ['microvm:create'] }],
})

