export const postV2NfsNfsIdActionsRoute = createRoute({
  method: 'post',
  path: '/v2/nfs/{nfs_id}/actions',
  tags: ['NFS Actions'],
  summary: 'Initiate an NFS action',
  description:
    'To execute an action (such as resize) on a specified NFS share, \nsend a POST request to `/v2/nfs/{nfs_id}/actions`. In the JSON body \nto the request, set the `type` attribute to on of the supported action types:\n\n| Action                           | Details |\n| -------------------------------- | ----------- |\n| <nobr>`resize`</nobr>            | Resizes an NFS share. Set the size_gib attribute to a desired value in GiB |\n| <nobr>`snapshot`</nobr>          | Takes a snapshot of an NFS share |\n| <nobr>`attach`</nobr>            | Attaches an NFS share to a VPC. Set the vpc_id attribute to the desired VPC ID |\n| <nobr>`detach`</nobr>            | Detaches an NFS share from a VPC. Set the vpc_id attribute to the desired VPC ID |\n| <nobr>`reassign`</nobr>          | Reassigns an NFS share from one VPC to another. Set the old_vpc_id and new_vpc_id attributes to the desired VPC IDs |\n| <nobr>`switch_performance_tier`</nobr> | Switches the performance tier of an NFS share. Set the performance_tier attribute to the desired tier (e.g., standard, high) |\n',
  operationId: 'nfs_create_action',
  request: {
    params: z.object({ nfs_id: NfsIdParamsSchema }),
    body: {
      description:
        'The `type` attribute set in the request body will specify the  action that\nwill be taken on the NFS share. Some actions will require additional\nattributes to be set as well.\n',
      content: {
        'application/json': {
          schema: z
            .union([
              NfsActionResizeSchema,
              NfsActionSnapshotSchema,
              NfsActionAttachSchema,
              NfsActionDetachSchema,
              NfsActionReassignSchema,
              NfsActionSwitchPerformanceTierSchema,
            ])
            .openapi({
              discriminator: {
                propertyName: 'type',
                mapping: {
                  resize: '#/components/schemas/nfs_action_resize',
                  snapshot: '#/components/schemas/nfs_action_snapshot',
                  attach: '#/components/schemas/nfs_action_attach',
                  detach: '#/components/schemas/nfs_action_detach',
                  reassign: '#/components/schemas/nfs_action_reassign',
                  switch_performance_tier:
                    '#/components/schemas/nfs_action_switch_performance_tier',
                },
              },
            }),
        },
      },
      required: true,
    },
  },
  responses: {
    201: NfsActionsResponse,
    401: UnauthorizedResponse,
    404: NotFoundResponse,
    429: TooManyRequestsResponse,
    500: ServerErrorResponse,
    default: UnexpectedErrorResponse,
  },
  security: [{ bearer_auth: ['nfs:create'] }],
})

