export const putV2SecuritySettingsPlanRoute = createRoute({
  method: 'put',
  path: '/v2/security/settings/plan',
  tags: ['Security'],
  summary: 'Update Plan',
  description: 'To update CSPM plan coverage, send a PUT request to `/v2/security/settings/plan`.',
  operationId: 'security_update_settings_plan',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              tier_coverage: z
                .record(
                  z.string(),
                  z
                    .object({
                      resources: z
                        .array(z.string())
                        .default([])
                        .exactOptional()
                        .openapi({
                          description: 'The URNs of resources to scan for the tier.',
                          example: ['do:droplet:fe3a2fd7-903d-46e6-ada3-3e4f285fb89d'],
                        }),
                      tags: z
                        .array(z.string())
                        .default([])
                        .exactOptional()
                        .openapi({
                          description: 'Resource tags to scan for the tier.',
                          example: ['production'],
                        }),
                    })
                    .openapi({ required: [] }),
                )
                .exactOptional()
                .openapi({
                  description: 'Scan coverage for each available plan tier.',
                  example: {
                    basic: {
                      resources: ['do:droplet:fe3a2fd7-903d-46e6-ada3-3e4f285fb89d'],
                      tags: ['production'],
                    },
                  },
                }),
            })
            .openapi({ required: [] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: TierCoverageResponse,
    400: BadRequestResponse,
    401: UnauthorizedResponse,
    404: NotFoundResponse,
    429: TooManyRequestsResponse,
    500: ServerErrorResponse,
    default: UnexpectedErrorResponse,
  },
  security: [{ bearer_auth: ['security:update'] }],
})

