export const getV2SnapshotsRoute = createRoute({
  method: 'get',
  path: '/v2/snapshots',
  tags: ['Snapshots'],
  summary: 'List All Snapshots',
  description:
    "To list all of the snapshots available on your account, send a GET request to\n`/v2/snapshots`.\n\nThe response will be a JSON object with a key called `snapshots`. This will be\nset to an array of `snapshot` objects, each of which will contain the standard\nsnapshot attributes.\n\n### Filtering Results by Resource Type\n\nIt's possible to request filtered results by including certain query parameters.\n\n#### List Droplet Snapshots\n\nTo retrieve only snapshots based on Droplets, include the `resource_type`\nquery parameter set to `droplet`. For example, `/v2/snapshots?resource_type=droplet`.\n\n#### List Volume Snapshots\n\nTo retrieve only snapshots based on volumes, include the `resource_type`\nquery parameter set to `volume`. For example, `/v2/snapshots?resource_type=volume`.\n",
  operationId: 'snapshots_list',
  request: {
    query: z.object({
      per_page: ParametersPerPageParamsSchema,
      page: PageParamsSchema,
      resource_type: SnapshotResourceTypeParamsSchema,
    }),
  },
  responses: {
    200: SnapshotsResponse,
    401: UnauthorizedResponse,
    429: TooManyRequestsResponse,
    500: ServerErrorResponse,
    default: UnexpectedErrorResponse,
  },
  security: [{ bearer_auth: ['snapshot:read'] }],
})

