export const postV2SpacesKeysRoute = createRoute({
  method: 'post',
  path: '/v2/spaces/keys',
  tags: ['Spaces Keys'],
  summary: 'Create a New Spaces Access Key',
  description:
    'To create a new Spaces Access Key, send a POST request to `/v2/spaces/keys`.\nAt the moment, you cannot mix a fullaccess permission with scoped permissions.\nA fullaccess permission will be prioritized if fullaccess and scoped permissions are both added.\n',
  operationId: 'spacesKey_create',
  request: {
    body: {
      content: {
        'application/json': {
          schema: KeySchema,
          examples: {
            'Read Only Key': {
              value: {
                name: 'read-only-key',
                grants: [{ bucket: 'my-bucket', permission: 'read' }],
              },
            },
            'Read Write Key': {
              value: {
                name: 'read-write-key',
                grants: [{ bucket: 'my-bucket', permission: 'readwrite' }],
              },
            },
            'Full Access Key': {
              value: {
                name: 'full-access-key',
                grants: [{ bucket: '', permission: 'fullaccess' }],
              },
            },
            'Mixed Permissions Key': {
              value: {
                name: 'mixed-permissions-key',
                grants: [
                  { bucket: 'my-bucket', permission: 'read' },
                  { bucket: 'my-bucket2', permission: 'readwrite' },
                ],
              },
            },
            'No Grant Key': { value: { name: 'no-grant-key', grants: [] } },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    201: KeyCreateResponse,
    400: BadRequest_3Response,
    401: UnauthorizedResponse,
    429: TooManyRequestsResponse,
    500: ServerErrorResponse,
    default: UnexpectedErrorResponse,
  },
  security: [{ bearer_auth: ['spaces_key:create_credentials'] }],
})

