export const getV2GenAiEvaluationRunsEvaluationRunUuidResultsRoute = createRoute({
  method: 'get',
  path: '/v2/gen-ai/evaluation_runs/{evaluation_run_uuid}/results',
  tags: ['Agent Platform API'],
  summary: 'Retrieve Results of an Evaluation Run',
  description:
    'To retrieve results of an evaluation run, send a GET request to `/v2/gen-ai/evaluation_runs/{evaluation_run_uuid}/results`.',
  operationId: 'genai_get_evaluation_run_results',
  request: {
    params: z.object({
      evaluation_run_uuid: z
        .string()
        .openapi({
          param: {
            description: 'Evaluation run UUID.',
            example: '"123e4567-e89b-12d3-a456-426614174000"',
            in: 'path',
            name: 'evaluation_run_uuid',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Page number.',
            example: 1,
            in: 'query',
            name: 'page',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Items per page.',
            example: 1,
            in: 'query',
            name: 'per_page',
            schema: { type: 'integer' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'A successful response.',
      content: { 'application/json': { schema: ApiGetEvaluationRunResultsOutputSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    401: UnauthorizedResponse,
    404: NotFoundResponse,
    429: TooManyRequestsResponse,
    500: ServerErrorResponse,
    default: UnexpectedErrorResponse,
  },
  security: [{ bearer_auth: ['genai:read'] }],
})

