export const getV2GenAiModelsRoute = createRoute({
  method: 'get',
  path: '/v2/gen-ai/models',
  tags: ['Agent Platform API'],
  summary: 'List Available Models',
  description: 'To list all models, send a GET request to `/v2/gen-ai/models`.',
  operationId: 'genai_list_models',
  request: {
    query: z.object({
      usecases: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(
            z.enum([
              'MODEL_USECASE_UNKNOWN',
              'MODEL_USECASE_AGENT',
              'MODEL_USECASE_FINETUNED',
              'MODEL_USECASE_KNOWLEDGEBASE',
              'MODEL_USECASE_GUARDRAIL',
              'MODEL_USECASE_REASONING',
              'MODEL_USECASE_SERVERLESS',
            ]),
          ),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'Include only models defined for the listed usecases.\n\n - MODEL_USECASE_UNKNOWN: The use case of the model is unknown\n - MODEL_USECASE_AGENT: The model maybe used in an agent\n - MODEL_USECASE_FINETUNED: The model maybe used for fine tuning\n - MODEL_USECASE_KNOWLEDGEBASE: The model maybe used for knowledge bases (embedding models)\n - MODEL_USECASE_GUARDRAIL: The model maybe used for guardrails\n - MODEL_USECASE_REASONING: The model usecase for reasoning\n - MODEL_USECASE_SERVERLESS: The model usecase for serverless inference',
            example: ['MODEL_USECASE_UNKNOWN'],
            in: 'query',
            name: 'usecases',
            schema: {
              items: {
                enum: [
                  'MODEL_USECASE_UNKNOWN',
                  'MODEL_USECASE_AGENT',
                  'MODEL_USECASE_FINETUNED',
                  'MODEL_USECASE_KNOWLEDGEBASE',
                  'MODEL_USECASE_GUARDRAIL',
                  'MODEL_USECASE_REASONING',
                  'MODEL_USECASE_SERVERLESS',
                ],
                type: 'string',
              },
              type: 'array',
            },
            required: false,
          },
        }),
      public_only: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description: 'Only include models that are publicly available.',
            example: true,
            in: 'query',
            name: 'public_only',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Page number.',
            example: 1,
            in: 'query',
            name: 'page',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Items per page.',
            example: 1,
            in: 'query',
            name: 'per_page',
            schema: { type: 'integer' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'A successful response.',
      content: { 'application/json': { schema: ApiListModelsOutputPublicSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    401: UnauthorizedResponse,
    404: NotFoundResponse,
    429: TooManyRequestsResponse,
    500: ServerErrorResponse,
    default: UnexpectedErrorResponse,
  },
  security: [{ bearer_auth: ['genai:read'] }],
})

