export const getV2GenAiScenarioSetsScenarioSetUuidScenariosRoute = createRoute({
  method: 'get',
  path: '/v2/gen-ai/scenario_sets/{scenario_set_uuid}/scenarios',
  tags: ['Agent Platform API'],
  summary: 'List Scenarios',
  description:
    'To list the scenarios in a scenario set, send a GET request to `/v2/gen-ai/scenario_sets/{scenario_set_uuid}/scenarios`.',
  operationId: 'genai_list_scenarios',
  request: {
    params: z.object({
      scenario_set_uuid: z
        .string()
        .openapi({
          param: {
            description: 'UUID of the scenario set to read.',
            example: '"123e4567-e89b-12d3-a456-426614174000"',
            in: 'path',
            name: 'scenario_set_uuid',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Page number.',
            example: 1,
            in: 'query',
            name: 'page',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Items per page.',
            example: 1,
            in: 'query',
            name: 'per_page',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      search: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Free-text search across name, description, and user_persona\n(case-insensitive substring match). Empty means no search.',
            example: 'example string',
            in: 'query',
            name: 'search',
            schema: { type: 'string' },
            required: false,
          },
        }),
      sort_by: z
        .enum([
          'SCENARIO_SORT_FIELD_UNSPECIFIED',
          'SCENARIO_SORT_FIELD_FILE_ORDER',
          'SCENARIO_SORT_FIELD_NAME',
          'SCENARIO_SORT_FIELD_DESCRIPTION',
        ])
        .default('SCENARIO_SORT_FIELD_UNSPECIFIED')
        .exactOptional()
        .openapi({
          param: {
            description:
              'Field to sort by. Defaults to original file order when unspecified.\n\n - SCENARIO_SORT_FIELD_FILE_ORDER: Preserve original file order. Default.\n - SCENARIO_SORT_FIELD_NAME: Sort by scenario name (case-insensitive). Empty names sort last.\n - SCENARIO_SORT_FIELD_DESCRIPTION: Sort by scenario description (case-insensitive).',
            example: 'SCENARIO_SORT_FIELD_UNSPECIFIED',
            in: 'query',
            name: 'sort_by',
            schema: {
              default: 'SCENARIO_SORT_FIELD_UNSPECIFIED',
              enum: [
                'SCENARIO_SORT_FIELD_UNSPECIFIED',
                'SCENARIO_SORT_FIELD_FILE_ORDER',
                'SCENARIO_SORT_FIELD_NAME',
                'SCENARIO_SORT_FIELD_DESCRIPTION',
              ],
              type: 'string',
            },
            required: false,
          },
        }),
      sort_direction: z
        .enum(['SORT_DIRECTION_UNSPECIFIED', 'SORT_DIRECTION_ASC', 'SORT_DIRECTION_DESC'])
        .default('SORT_DIRECTION_UNSPECIFIED')
        .exactOptional()
        .openapi({
          param: {
            description: 'Sort direction. Defaults to ascending when unspecified.',
            example: 'SORT_DIRECTION_UNSPECIFIED',
            in: 'query',
            name: 'sort_direction',
            schema: {
              default: 'SORT_DIRECTION_UNSPECIFIED',
              enum: ['SORT_DIRECTION_UNSPECIFIED', 'SORT_DIRECTION_ASC', 'SORT_DIRECTION_DESC'],
              type: 'string',
            },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'A successful response.',
      content: { 'application/json': { schema: ApiListScenariosOutputSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    401: UnauthorizedResponse,
    404: NotFoundResponse,
    429: TooManyRequestsResponse,
    500: ServerErrorResponse,
    default: UnexpectedErrorResponse,
  },
  security: [{ bearer_auth: ['genai:read'] }],
})

