export const getV2GenAiSimulationRunsRunUuidEpisodesRoute = createRoute({
  method: 'get',
  path: '/v2/gen-ai/simulation_runs/{run_uuid}/episodes',
  tags: ['Agent Platform API'],
  summary: 'List Simulation Episodes',
  description:
    'To list the episodes within a simulation run, send a GET request to `/v2/gen-ai/simulation_runs/{run_uuid}/episodes`.',
  operationId: 'genai_list_simulation_episodes',
  request: {
    params: z.object({
      run_uuid: z
        .string()
        .openapi({
          param: {
            description: 'UUID of the run whose episodes to list.',
            example: '"123e4567-e89b-12d3-a456-426614174000"',
            in: 'path',
            name: 'run_uuid',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      scenario_uuid: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Optional filter by scenario.',
            example: '123e4567-e89b-12d3-a456-426614174000',
            in: 'query',
            name: 'scenario_uuid',
            schema: { type: 'string' },
            required: false,
          },
        }),
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Page number.',
            example: 1,
            in: 'query',
            name: 'page',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Items per page.',
            example: 1,
            in: 'query',
            name: 'per_page',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      statuses: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(
            z.enum([
              'SIMULATION_EPISODE_STATUS_UNSPECIFIED',
              'SIMULATION_EPISODE_STATUS_RUNNING',
              'SIMULATION_EPISODE_STATUS_FINISHED',
              'SIMULATION_EPISODE_STATUS_FAILED',
              'SIMULATION_EPISODE_STATUS_PREPARING',
            ]),
          ),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'Filter by one or more statuses. Empty means no status filter.\n\n - SIMULATION_EPISODE_STATUS_RUNNING: The episode is executing and a trajectory is available to retrieve.\n - SIMULATION_EPISODE_STATUS_FINISHED: The episode reached a stop condition and produced a verdict.\n - SIMULATION_EPISODE_STATUS_FAILED: The episode failed because of a cancel, timeout, or error.\n - SIMULATION_EPISODE_STATUS_PREPARING: The episode is allocated but its trajectory is not available yet.',
            example: ['SIMULATION_EPISODE_STATUS_FINISHED'],
            in: 'query',
            name: 'statuses',
            schema: {
              items: {
                enum: [
                  'SIMULATION_EPISODE_STATUS_UNSPECIFIED',
                  'SIMULATION_EPISODE_STATUS_RUNNING',
                  'SIMULATION_EPISODE_STATUS_FINISHED',
                  'SIMULATION_EPISODE_STATUS_FAILED',
                  'SIMULATION_EPISODE_STATUS_PREPARING',
                ],
                type: 'string',
              },
              type: 'array',
            },
            required: false,
          },
        }),
      verdicts: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(
            z.enum([
              'SIMULATION_EPISODE_VERDICT_UNSPECIFIED',
              'SIMULATION_EPISODE_VERDICT_SUCCESS',
              'SIMULATION_EPISODE_VERDICT_FAILURE',
              'SIMULATION_EPISODE_VERDICT_INCONCLUSIVE',
            ]),
          ),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              "Filter by one or more verdicts. Empty means no verdict filter.\n\n - SIMULATION_EPISODE_VERDICT_SUCCESS: The candidate agent satisfied the scenario's stopping criteria.\n - SIMULATION_EPISODE_VERDICT_FAILURE: The candidate agent did not satisfy the stopping criteria.\n - SIMULATION_EPISODE_VERDICT_INCONCLUSIVE: No conclusive verdict (e.g. max_turns reached without the judge finishing).",
            example: ['SIMULATION_EPISODE_VERDICT_SUCCESS'],
            in: 'query',
            name: 'verdicts',
            schema: {
              items: {
                enum: [
                  'SIMULATION_EPISODE_VERDICT_UNSPECIFIED',
                  'SIMULATION_EPISODE_VERDICT_SUCCESS',
                  'SIMULATION_EPISODE_VERDICT_FAILURE',
                  'SIMULATION_EPISODE_VERDICT_INCONCLUSIVE',
                ],
                type: 'string',
              },
              type: 'array',
            },
            required: false,
          },
        }),
      search: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Free-text search across scenario_uuid and session_id\n(case-insensitive substring match). Empty means no search.',
            example: 'example string',
            in: 'query',
            name: 'search',
            schema: { type: 'string' },
            required: false,
          },
        }),
      sort_by: z
        .enum([
          'SIMULATION_EPISODE_SORT_FIELD_UNSPECIFIED',
          'SIMULATION_EPISODE_SORT_FIELD_SCENARIO',
          'SIMULATION_EPISODE_SORT_FIELD_CREATED_AT',
          'SIMULATION_EPISODE_SORT_FIELD_STATUS',
          'SIMULATION_EPISODE_SORT_FIELD_VERDICT',
        ])
        .default('SIMULATION_EPISODE_SORT_FIELD_UNSPECIFIED')
        .exactOptional()
        .openapi({
          param: {
            description:
              'Field to sort by. Defaults to scenario ordering when unspecified.\n\n - SIMULATION_EPISODE_SORT_FIELD_SCENARIO: Sort by scenario_uuid then episode_index. Default.\n - SIMULATION_EPISODE_SORT_FIELD_CREATED_AT: Sort by creation date.\n - SIMULATION_EPISODE_SORT_FIELD_STATUS: Sort by episode status using lifecycle order.\n - SIMULATION_EPISODE_SORT_FIELD_VERDICT: Sort by verdict (nulls last).',
            example: 'SIMULATION_EPISODE_SORT_FIELD_UNSPECIFIED',
            in: 'query',
            name: 'sort_by',
            schema: {
              default: 'SIMULATION_EPISODE_SORT_FIELD_UNSPECIFIED',
              enum: [
                'SIMULATION_EPISODE_SORT_FIELD_UNSPECIFIED',
                'SIMULATION_EPISODE_SORT_FIELD_SCENARIO',
                'SIMULATION_EPISODE_SORT_FIELD_CREATED_AT',
                'SIMULATION_EPISODE_SORT_FIELD_STATUS',
                'SIMULATION_EPISODE_SORT_FIELD_VERDICT',
              ],
              type: 'string',
            },
            required: false,
          },
        }),
      sort_direction: z
        .enum(['SORT_DIRECTION_UNSPECIFIED', 'SORT_DIRECTION_ASC', 'SORT_DIRECTION_DESC'])
        .default('SORT_DIRECTION_UNSPECIFIED')
        .exactOptional()
        .openapi({
          param: {
            description: 'Sort direction. Defaults to ascending when unspecified.',
            example: 'SORT_DIRECTION_UNSPECIFIED',
            in: 'query',
            name: 'sort_direction',
            schema: {
              default: 'SORT_DIRECTION_UNSPECIFIED',
              enum: ['SORT_DIRECTION_UNSPECIFIED', 'SORT_DIRECTION_ASC', 'SORT_DIRECTION_DESC'],
              type: 'string',
            },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'A successful response.',
      content: { 'application/json': { schema: ApiListSimulationEpisodesOutputSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    401: UnauthorizedResponse,
    404: NotFoundResponse,
    429: TooManyRequestsResponse,
    500: ServerErrorResponse,
    default: UnexpectedErrorResponse,
  },
  security: [{ bearer_auth: ['genai:read'] }],
})

