export const getV2GenAiWorkspacesWorkspaceUuidAgentsRoute = createRoute({
  method: 'get',
  path: '/v2/gen-ai/workspaces/{workspace_uuid}/agents',
  tags: ['Agent Platform API'],
  summary: 'List agents by Workspace',
  description:
    'To list all agents by a Workspace, send a GET request to `/v2/gen-ai/workspaces/{workspace_uuid}/agents`.',
  operationId: 'genai_list_agents_by_workspace',
  request: {
    params: z.object({
      workspace_uuid: z
        .string()
        .openapi({
          param: {
            description: 'Workspace UUID.',
            example: '"123e4567-e89b-12d3-a456-426614174000"',
            in: 'path',
            name: 'workspace_uuid',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      only_deployed: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description: 'Only list agents that are deployed.',
            example: true,
            in: 'query',
            name: 'only_deployed',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Page number.',
            example: 1,
            in: 'query',
            name: 'page',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Items per page.',
            example: 1,
            in: 'query',
            name: 'per_page',
            schema: { type: 'integer' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'A successful response.',
      content: { 'application/json': { schema: ApiListAgentsByWorkspaceOutputSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    401: UnauthorizedResponse,
    404: NotFoundResponse,
    429: TooManyRequestsResponse,
    500: ServerErrorResponse,
    default: UnexpectedErrorResponse,
  },
  security: [{ bearer_auth: ['genai:read'] }],
})

