export const putUploadUrlRoute = createRoute({
  method: 'put',
  path: '/<upload_url>',
  tags: ['Batch Inference'],
  summary: 'Upload a Batch Inference Input File',
  description:
    'Uploads the raw JSONL bytes to the presigned `upload_url` returned by `POST /v1/batches/files`.\n\n**The URL is dynamic — do not construct it.** Use the `upload_url` value from the previous step verbatim. Its host, path, and query parameters are part of the short-lived (~15 minute) signature and change per request; the server and path shown here are illustrative. If the URL expires before the upload completes, create a new file intent and retry.\n\n`POST /v1/batches` performs a `HEAD` check on the uploaded object and will reject the batch if this upload has not completed.\n\nSend the raw JSONL bytes verbatim. Presigned PUT URLs are signature-sensitive to request headers — prefer `application/octet-stream` or omit `Content-Type` entirely. A custom value (for example `application/jsonl`) can cause signature mismatches unless the URL was signed for that exact header.\n',
  operationId: 'inference_upload_batch_file',
  request: {
    body: {
      description: 'Raw JSONL bytes — one request per line.',
      content: {
        'application/octet-stream': {
          schema: z.file().openapi({ type: 'string', format: 'binary' }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Upload accepted by object storage.',
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    401: UnauthorizedResponse,
    403: {
      description:
        'Signature mismatch or URL expired. Create a new file intent with `POST /v1/batches/files` and upload again.\n',
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    429: TooManyRequestsResponse,
    500: ServerErrorResponse,
    default: UnexpectedErrorResponse,
  },
  security: [],
  servers: [
    {
      url: 'https://',
      description:
        'Use the exact `upload_url` returned by `POST /v1/batches/files`. Do not construct this URL — it is presigned, short-lived, and different per request.\n',
    },
  ],
})

export const getV1BatchesRoute = createRoute({
  method: 'get',
  path: '/v1/batches',
  tags: ['Batch Inference'],
  summary: 'List Batch Inference Jobs',
  description:
    'Returns a cursor-paginated list of batch jobs, ordered newest first. Use `limit` to control page size and `after` to page forward using the `last_id` from the previous response.\n',
  operationId: 'inference_list_batches',
  request: {
    query: z.object({
      after: z
        .uuid()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'after',
            description:
              'Cursor for pagination. Pass the `last_id` value from the previous response to fetch the next page. Omit for the first page.\n',
            required: false,
            schema: { type: 'string', format: 'uuid' },
            example: '7b2e9c1a-6f4d-4d9b-a0f1-5c4b7e2f8a12',
          },
        }),
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(100),
        )
        .default(20)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'limit',
            description: 'Maximum number of batches to return per page.',
            required: false,
            schema: { type: 'integer', minimum: 1, maximum: 100, default: 20 },
            example: 20,
          },
        }),
      status: z
        .enum([
          'validating',
          'in_progress',
          'finalizing',
          'completed',
          'failed',
          'expired',
          'cancelling',
          'cancelled',
        ])
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'status',
            description:
              'Optional filter restricting results to batches in the given lifecycle state.\n',
            required: false,
            schema: {
              type: 'string',
              enum: [
                'validating',
                'in_progress',
                'finalizing',
                'completed',
                'failed',
                'expired',
                'cancelling',
                'cancelled',
              ],
            },
            example: 'in_progress',
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Page of batch jobs.',
      content: { 'application/json': { schema: BatchListResponseSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    401: UnauthorizedResponse,
    403: Forbidden_2Response,
    429: TooManyRequestsResponse,
    500: ServerErrorResponse,
    default: UnexpectedErrorResponse,
  },
  security: [{ inference_bearer_auth: [] }],
  servers: [{ url: 'https://inference.do-ai.run', description: 'production' }],
})

export const postV1BatchesRoute = createRoute({
  method: 'post',
  path: '/v1/batches',
  tags: ['Batch Inference'],
  summary: 'Create a Batch Inference Job',
  description:
    'Submits a batch job against a previously uploaded JSONL input file. The upload must have completed before this call; otherwise the request is rejected.\n\nSupply a unique `request_id` to make the submission idempotent — retries with the same value return the existing job. When `provider` is `openai`, the `url` on each JSONL line must match `endpoint`.\n',
  operationId: 'inference_create_batch',
  request: {
    body: {
      content: {
        'application/json': {
          schema: BatchCreateRequestSchema,
          examples: {
            'OpenAI Chat Completions': {
              value: {
                file_id: 'a1b2c3d4-e5f6-4789-90ab-cdef12345678',
                provider: 'openai',
                endpoint: '/v1/chat/completions',
                completion_window: '24h',
                request_id: 'c7e3ad1e-20c3-4e47-9bf2-6f2a4d6a2f11',
              },
            },
            'OpenAI Responses': {
              value: {
                file_id: 'a1b2c3d4-e5f6-4789-90ab-cdef12345678',
                provider: 'openai',
                endpoint: '/v1/responses',
                completion_window: '24h',
                request_id: '9f7b9d4a-4e6c-4a27-8e35-1b0e4c5a9a12',
              },
            },
            'Anthropic Messages': {
              value: {
                file_id: 'a1b2c3d4-e5f6-4789-90ab-cdef12345678',
                provider: 'anthropic',
                completion_window: '24h',
                request_id: '2f1a7d9e-8c03-4d2c-9b7e-6f8e2b1a4c77',
                metadata: { team: 'ml-eval', dataset: 'prompts_v1' },
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Batch job accepted. Poll `GET /v1/batches/{batch_id}` for status.',
      content: { 'application/json': { schema: BatchSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    400: BadRequestResponse,
    401: UnauthorizedResponse,
    403: Forbidden_2Response,
    404: NotFoundResponse,
    409: ConflictResponse,
    422: UnprocessableEntityResponse,
    429: TooManyRequestsResponse,
    500: ServerErrorResponse,
    default: UnexpectedErrorResponse,
  },
  security: [{ inference_bearer_auth: [] }],
  servers: [{ url: 'https://inference.do-ai.run', description: 'production' }],
})

