export const getV1BatchesBatchIdResultsRoute = createRoute({
  method: 'get',
  path: '/v1/batches/{batch_id}/results',
  tags: ['Batch Inference'],
  summary: 'Get Batch Inference Results Download Links',
  description:
    'Returns short-lived presigned download URLs for the output (and optional error sidecar) of a completed batch job. If results are not yet ready, the response sets `result_available: false` or returns `412 Precondition Failed`; in both cases, keep polling batch status and retry.\n\nDownload the artifacts soon after fetching — the URLs are short-lived. Result files themselves are retained for up to 30 days after the job completes, after which they are deleted.\n',
  operationId: 'inference_get_batch_results',
  request: {
    params: z.object({
      batch_id: z
        .uuid()
        .openapi({
          param: {
            in: 'path',
            name: 'batch_id',
            description: 'The batch job identifier.',
            required: true,
            schema: { type: 'string', format: 'uuid' },
            example: '0e9d1d35-3d1e-4d66-9a2f-8c7e0f6b3e21',
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Presigned download URLs.',
      content: { 'application/json': { schema: BatchResultsResponseSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    401: UnauthorizedResponse,
    403: Forbidden_2Response,
    404: NotFoundResponse,
    412: {
      description: 'Results are not yet available. Poll batch status and retry.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          example: {
            id: 'precondition_failed',
            message: 'Batch results are not yet available. Retry once the job has completed.',
          },
        },
      },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    429: TooManyRequestsResponse,
    500: ServerErrorResponse,
    default: UnexpectedErrorResponse,
  },
  security: [{ inference_bearer_auth: [] }],
  servers: [{ url: 'https://inference.do-ai.run', description: 'production' }],
})

export const postV1BatchesBatchIdCancelRoute = createRoute({
  method: 'post',
  path: '/v1/batches/{batch_id}/cancel',
  tags: ['Batch Inference'],
  summary: 'Cancel a Batch Inference Job',
  description:
    'Requests cancellation of a batch job. The job transitions to `cancelling` and, once in-flight requests drain, to `cancelled`. Jobs already in a terminal state (`completed`, `failed`, `expired`, `cancelled`) cannot be cancelled and return `409 Conflict`. Cancellation is also rejected with `409 Conflict` while the job has not yet been submitted to the upstream provider — there is nothing to cancel until the provider batch id is assigned.\n\nPartial results produced before cancellation remain available via `GET /v1/batches/{batch_id}/results`.\n',
  operationId: 'inference_cancel_batch',
  request: {
    params: z.object({
      batch_id: z
        .uuid()
        .openapi({
          param: {
            in: 'path',
            name: 'batch_id',
            description: 'The batch job identifier.',
            required: true,
            schema: { type: 'string', format: 'uuid' },
            example: '0e9d1d35-3d1e-4d66-9a2f-8c7e0f6b3e21',
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Cancellation accepted. Returns the updated batch job.',
      content: { 'application/json': { schema: BatchSchema } },
      headers: z.object({
        'ratelimit-limit': RatelimitLimitHeaderSchema,
        'ratelimit-remaining': RatelimitRemainingHeaderSchema,
        'ratelimit-reset': RatelimitResetHeaderSchema,
      }),
    },
    401: UnauthorizedResponse,
    403: Forbidden_2Response,
    404: NotFoundResponse,
    409: ConflictResponse,
    429: TooManyRequestsResponse,
    500: ServerErrorResponse,
    default: UnexpectedErrorResponse,
  },
  security: [{ inference_bearer_auth: [] }],
  servers: [{ url: 'https://inference.do-ai.run', description: 'production' }],
})
